import { Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { AuthRequest } from '../middleware/auth';

const prisma = new PrismaClient();

// Get overall statistics
export const getStats = async (_req: AuthRequest, res: Response) => {
  try {
    const [totalBooks, totalBorrowed, activeUsers, overdueBooks] = await Promise.all([
      prisma.book.count(),
      prisma.loan.count({
        where: { returnDate: null }
      }),
      prisma.user.count({
        where: {
          loans: {
            some: {
              returnDate: null
            }
          }
        }
      }),
      prisma.loan.count({
        where: {
          returnDate: null,
          dueDate: {
            lt: new Date()
          }
        }
      })
    ]);

    res.json({
      totalBooks,
      activeUsers,
      totalBorrowed,
      overdueBooks
    });
  } catch (error) {
    console.error('Error fetching stats:', error);
    res.status(500).json({ error: 'Không thể tải thống kê' });
  }
};

// Get borrow trends by month
export const getBorrowTrends = async (req: AuthRequest, res: Response) => {
  try {
    const year = parseInt(req.query.year as string) || new Date().getFullYear();

    const loans = await prisma.loan.findMany({
      where: {
        borrowDate: {
          gte: new Date(`${year}-01-01`),
          lte: new Date(`${year}-12-31`)
        }
      },
      select: {
        borrowDate: true
      }
    });

    // Group by month
    const monthlyData = Array.from({ length: 12 }, (_, i) => ({
      month: i + 1,
      count: 0
    }));

    loans.forEach(loan => {
      const month = new Date(loan.borrowDate).getMonth();
      monthlyData[month].count++;
    });

    res.json(monthlyData);
  } catch (error) {
    console.error('Error fetching borrow trends:', error);
    res.status(500).json({ error: 'Không thể tải xu hướng mượn sách' });
  }
};

// Get top borrowed books
export const getTopBooks = async (req: AuthRequest, res: Response) => {
  try {
    const limit = parseInt(req.query.limit as string) || 5;

    // Fetch loans with related BookItem and Book
    const loans = await prisma.loan.findMany({
      include: {
        bookItem: {
          include: {
            book: {
              include: {
                author: true,
                category: true
              }
            }
          }
        }
      }
    });

    // Count loans per Book
    const bookCountMap = new Map<number, { book: any; borrowCount: number }>();
    for (const loan of loans) {
      const book = loan.bookItem?.book;
      if (book) {
        const existing = bookCountMap.get(book.id) || { book, borrowCount: 0 };
        existing.borrowCount += 1;
        bookCountMap.set(book.id, existing);
      }
    }

    const sorted = Array.from(bookCountMap.values())
      .sort((a, b) => b.borrowCount - a.borrowCount)
      .slice(0, limit)
      .map(item => ({
        id: item.book.id,
        title: item.book.title,
        isbn: item.book.isbn,
        author: item.book.author?.name || '',
        category: item.book.category?.name || '',
        coverImage: item.book.coverImage,
        borrowCount: item.borrowCount
      }));

    res.json(sorted);
  } catch (error) {
    console.error('Error fetching top books:', error);
    res.status(500).json({ error: 'Không thể tải sách phổ biến' });
  }
};

// Get recent loan activities
export const getRecentActivity = async (req: AuthRequest, res: Response) => {
  try {
    const limit = parseInt(req.query.limit as string) || 10;

    const recentLoans = await prisma.loan.findMany({
      take: limit,
      orderBy: {
        borrowDate: 'desc'
      },
      include: {
        user: {
          select: {
            name: true,
            email: true
          }
        },
        bookItem: {
          include: {
            book: {
              select: {
                title: true
              }
            }
          }
        }
      }
    });

    const activities = recentLoans.map(loan => ({
      id: loan.id,
      userName: loan.user?.name || 'Độc giả',
      bookTitle: loan.bookItem?.book?.title || 'Sách',
      action: loan.returnDate ? 'returned' : 'borrowed',
      date: loan.returnDate || loan.borrowDate,
      borrowDate: loan.borrowDate,
      returnDate: loan.returnDate
    }));

    res.json(activities);
  } catch (error) {
    console.error('Error fetching recent activity:', error);
    res.status(500).json({ error: 'Không thể tải hoạt động gần đây' });
  }
};

import { Request, Response } from 'express';
import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { AuthRequest } from '../middleware/auth';
import { sendPasswordResetOtpEmail, sendLoginOtpEmail } from '../services/mailService';
import { createNotification } from '../services/notificationService';

const prisma = new PrismaClient();

export const register = async (req: Request, res: Response) => {
  const { email, password, name } = req.body;
  const hashedPassword = await bcrypt.hash(password, 10);

  try {
    await prisma.user.create({
      data: {
        email,
        password: hashedPassword,
        name,
        role: 'USER',
      },
    });
    res.status(201).json({ message: 'User created' });
  } catch (error) {
    res.status(400).json({ error: 'User already exists' });
  }
};

export const login = async (req: Request, res: Response) => {
  try {
    const { email, password } = req.body;
    if (!email || !password) {
      return res.status(400).json({ error: 'Vui lòng nhập đầy đủ email và mật khẩu' });
    }

    const cleanEmail = String(email).trim().toLowerCase();
    const user = await prisma.user.findUnique({ where: { email: cleanEmail } });

    if (!user || !(await bcrypt.compare(password, user.password))) {
      return res.status(401).json({ error: 'Tài khoản hoặc mật khẩu không chính xác' });
    }

    // KIỂM TRA BẢO MẬT: Nếu tài khoản yêu cầu OTP (2FA đã bật hoặc cần xác minh)
    if (user.twoFactorEnabled) {
      // TUYỆT ĐỐI KHÔNG được tạo và trả về Access Token / Refresh Token thật ở bước này!
      const otp = Math.floor(100000 + Math.random() * 900000).toString();
      const expiryDate = new Date(Date.now() + 10 * 60 * 1000); // Hiệu lực 10 phút

      await prisma.user.update({
        where: { id: user.id },
        data: {
          loginOtp: otp,
          loginOtpExpiry: expiryDate,
        },
      });

      console.log(`[AUTH 2FA] 🔐 Đã tạo mã OTP đăng nhập cho ${user.email}: ${otp}`);

      // Gửi email chứa mã OTP
      let previewUrl: string | undefined = undefined;
      try {
        const mailResult = await sendLoginOtpEmail({
          to: user.email,
          userName: user.name,
          otp,
          expiryMinutes: 10,
        });
        if (mailResult.previewUrl) {
          previewUrl = mailResult.previewUrl;
        }
      } catch (mailError) {
        console.error('[AUTH 2FA] Lỗi khi gửi email OTP:', mailError);
      }

      // CHỈ trả về HTTP 200 với payload báo hiệu cần OTP, không có token
      return res.status(200).json({
        requireOtp: true,
        tempUserId: user.id,
        email: user.email,
        message: 'Tài khoản yêu cầu xác thực 2 bước (2FA). Vui lòng nhập mã OTP để tiếp tục.',
        previewUrl,
      });
    }

    // Nếu không yêu cầu OTP, cấp token bình thường
    const token = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET as string,
      { expiresIn: '1h' }
    );

    return res.json({
      requireOtp: false,
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        membershipTier: user.membershipTier,
        isBlacklisted: user.isBlacklisted,
        twoFactorEnabled: user.twoFactorEnabled,
      }
    });
  } catch (error: any) {
    console.error('Error during login:', error);
    return res.status(500).json({ error: 'Đăng nhập thất bại, vui lòng thử lại sau' });
  }
};

/**
 * Xác thực mã OTP đăng nhập (Verify OTP)
 * CHỈ khi gọi API này với OTP và tempUserId chính xác, Backend mới sinh và cấp Token thật
 */
export const verifyOtp = async (req: Request, res: Response) => {
  try {
    const { tempUserId, otp } = req.body;

    if (!tempUserId || !otp) {
      return res.status(400).json({ error: 'Vui lòng cung cấp đầy đủ thông tin xác thực (tempUserId và mã OTP)' });
    }

    const userId = Number(tempUserId);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Mã định danh tạm thời không hợp lệ' });
    }

    const user = await prisma.user.findUnique({
      where: { id: userId }
    });

    if (!user) {
      return res.status(404).json({ error: 'Không tìm thấy phiên đăng nhập hoặc phiên đã hết hạn' });
    }

    const cleanOtp = String(otp).trim();

    // Kiểm tra tính chính xác của mã OTP
    if (!user.loginOtp || user.loginOtp !== cleanOtp) {
      return res.status(400).json({ error: 'Mã OTP không chính xác. Vui lòng kiểm tra lại.' });
    }

    // Kiểm tra thời hạn hiệu lực của mã OTP
    if (!user.loginOtpExpiry || new Date(user.loginOtpExpiry) < new Date()) {
      return res.status(400).json({ error: 'Mã OTP đã hết hạn. Vui lòng đăng nhập lại để nhận mã mới.' });
    }

    // Xác thực thành công: Xóa sạch mã OTP đăng nhập trong DB để tránh tái sử dụng
    await prisma.user.update({
      where: { id: user.id },
      data: {
        loginOtp: null,
        loginOtpExpiry: null,
      },
    });

    // CHỈ TẠI ĐÂY MỚI SINH RA ACCESS TOKEN THẬT ĐỂ CẤP CHO CLIENT
    const token = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET as string,
      { expiresIn: '1h' }
    );

    return res.json({
      message: 'Xác thực OTP thành công!',
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        membershipTier: user.membershipTier,
        isBlacklisted: user.isBlacklisted,
        twoFactorEnabled: user.twoFactorEnabled,
      }
    });
  } catch (error: any) {
    console.error('Error in verifyOtp:', error);
    return res.status(500).json({ error: 'Xác thực OTP thất bại, vui lòng thử lại sau' });
  }
};

/**
 * Gửi lại mã OTP đăng nhập
 */
export const resendLoginOtp = async (req: Request, res: Response) => {
  try {
    const { tempUserId } = req.body;
    if (!tempUserId) {
      return res.status(400).json({ error: 'Thiếu thông tin tempUserId' });
    }

    const userId = Number(tempUserId);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'tempUserId không hợp lệ' });
    }

    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return res.status(404).json({ error: 'Không tìm thấy tài khoản để gửi lại mã OTP' });
    }

    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const expiryDate = new Date(Date.now() + 10 * 60 * 1000);

    await prisma.user.update({
      where: { id: user.id },
      data: {
        loginOtp: otp,
        loginOtpExpiry: expiryDate,
      },
    });

    console.log(`[AUTH 2FA] 🔄 Gửi lại mã OTP đăng nhập cho ${user.email}: ${otp}`);

    let previewUrl: string | undefined = undefined;
    try {
      const mailResult = await sendLoginOtpEmail({
        to: user.email,
        userName: user.name,
        otp,
        expiryMinutes: 10,
      });
      if (mailResult.previewUrl) previewUrl = mailResult.previewUrl;
    } catch (e) {
      console.error('[AUTH 2FA] Lỗi khi gửi lại email OTP:', e);
    }

    return res.json({
      message: 'Mã OTP mới đã được gửi đến email của bạn!',
      previewUrl,
    });
  } catch (error: any) {
    console.error('Error in resendLoginOtp:', error);
    return res.status(500).json({ error: 'Không thể gửi lại mã OTP, vui lòng thử lại sau' });
  }
};

/**
 * Bật / Tắt 2FA
 */
export const toggleTwoFactor = async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const { enabled } = req.body;
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return res.status(404).json({ error: 'Không tìm thấy thông tin người dùng' });
    }

    const newStatus = typeof enabled === 'boolean' ? enabled : !user.twoFactorEnabled;

    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: { twoFactorEnabled: newStatus },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        membershipTier: true,
        isBlacklisted: true,
        twoFactorEnabled: true,
        createdAt: true,
      }
    });

    return res.json({
      message: newStatus ? 'Đã kích hoạt xác thực 2 bước (2FA)' : 'Đã tắt xác thực 2 bước (2FA)',
      twoFactorEnabled: newStatus,
      user: updatedUser,
    });
  } catch (error: any) {
    console.error('Error toggling 2FA:', error);
    return res.status(500).json({ error: 'Không thể cập nhật cấu hình 2FA' });
  }
};

export const getMe = async (req: AuthRequest, res: Response) => {
  if (!req.user) return res.status(401).json({ error: 'Not authenticated' });

  const user = await prisma.user.findUnique({
    where: { id: req.user.userId },
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      membershipTier: true,
      isBlacklisted: true,
      twoFactorEnabled: true,
      createdAt: true
    }
  });

  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json(user);
};

export const getAllUsers = async (_req: AuthRequest, res: Response) => {
  const users = await prisma.user.findMany({
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      membershipTier: true,
      isBlacklisted: true,
      createdAt: true
    },
    orderBy: { id: 'asc' }
  });
  res.json(users);
};

export const toggleBlacklist = async (req: AuthRequest, res: Response) => {
  try {
    const { id } = req.params;
    const { isBlacklisted } = req.body;

    const targetUser = await prisma.user.findUnique({
      where: { id: Number(id) }
    });

    if (!targetUser) {
      return res.status(404).json({ error: 'Không tìm thấy người dùng' });
    }

    // Không cho phép tự đưa chính mình vào danh sách đen
    if (targetUser.id === req.user?.userId) {
      return res.status(400).json({ error: 'Không thể tự đưa chính tài khoản của bạn vào danh sách đen' });
    }

    const newStatus = typeof isBlacklisted === 'boolean' ? isBlacklisted : !targetUser.isBlacklisted;

    const updatedUser = await prisma.user.update({
      where: { id: Number(id) },
      data: { isBlacklisted: newStatus },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        membershipTier: true,
        isBlacklisted: true,
        createdAt: true
      }
    });

    res.json({
      message: newStatus
        ? `Đã đưa độc giả "${updatedUser.name}" vào Danh sách Đen (chặn mượn sách).`
        : `Đã mở khóa và gỡ độc giả "${updatedUser.name}" khỏi Danh sách Đen.`,
      user: updatedUser
    });
  } catch (error) {
    console.error('Error toggling blacklist:', error);
    res.status(500).json({ error: 'Không thể cập nhật trạng thái danh sách đen' });
  }
};

export const changePassword = async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const { currentPassword, newPassword } = req.body;

    if (!currentPassword || !newPassword) {
      return res.status(400).json({ error: 'Vui lòng điền đầy đủ mật khẩu hiện tại và mật khẩu mới' });
    }

    if (newPassword.length < 6) {
      return res.status(400).json({ error: 'Mật khẩu mới phải có độ dài tối thiểu 6 ký tự' });
    }

    const user = await prisma.user.findUnique({
      where: { id: userId }
    });

    if (!user) {
      return res.status(404).json({ error: 'Không tìm thấy thông tin người dùng' });
    }

    // Kiểm tra mật khẩu hiện tại
    const isMatch = await bcrypt.compare(currentPassword, user.password);
    if (!isMatch) {
      return res.status(400).json({ error: 'Mật khẩu hiện tại không chính xác' });
    }

    // Kiểm tra xem mật khẩu mới có trùng mật khẩu cũ không
    if (currentPassword === newPassword) {
      return res.status(400).json({ error: 'Mật khẩu mới không được trùng với mật khẩu hiện tại' });
    }

    // Băm mật khẩu mới
    const hashedPassword = await bcrypt.hash(newPassword, 10);

    await prisma.user.update({
      where: { id: userId },
      data: { password: hashedPassword }
    });

    // Tạo thông báo cho người dùng
    await createNotification({
      userId,
      title: 'Đổi mật khẩu thành công',
      message: 'Mật khẩu tài khoản của bạn vừa được cập nhật thành công.',
    });

    res.json({ message: 'Đổi mật khẩu thành công!' });
  } catch (error) {
    console.error('Error changing password:', error);
    res.status(500).json({ error: 'Không thể cập nhật mật khẩu, vui lòng thử lại sau' });
  }
};

export const forgotPassword = async (req: Request, res: Response) => {
  try {
    const { email } = req.body;
    if (!email || typeof email !== 'string') {
      return res.status(400).json({ error: 'Vui lòng cung cấp địa chỉ email hợp lệ' });
    }

    const cleanEmail = email.trim().toLowerCase();
    const user = await prisma.user.findUnique({
      where: { email: cleanEmail }
    });

    if (!user) {
      return res.status(404).json({ error: 'Email không tồn tại trong hệ thống' });
    }

    // Tạo mã OTP ngẫu nhiên 6 chữ số
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    // Hạn 15 phút
    const expiryDate = new Date(Date.now() + 15 * 60 * 1000);

    // Lưu OTP vào DB
    await prisma.user.update({
      where: { id: user.id },
      data: {
        resetOtp: otp,
        resetOtpExpiry: expiryDate,
      },
    });

    // Gửi email OTP qua mailService
    const mailResult = await sendPasswordResetOtpEmail({
      to: user.email,
      userName: user.name,
      otp,
      expiryMinutes: 15,
    });

    res.json({
      message: 'Mã xác thực OTP đã được gửi đến email của bạn. Vui lòng kiểm tra hộp thư (kể cả hòm thư rác/spam).',
      previewUrl: mailResult.previewUrl || undefined,
    });
  } catch (error: any) {
    console.error('Error in forgotPassword:', error);
    res.status(500).json({ error: 'Không thể gửi mã xác nhận OTP, vui lòng thử lại sau' });
  }
};

export const resetPassword = async (req: Request, res: Response) => {
  try {
    const { email, otp, newPassword } = req.body;

    if (!email || !otp || !newPassword) {
      return res.status(400).json({ error: 'Vui lòng cung cấp đầy đủ email, mã OTP và mật khẩu mới' });
    }

    if (typeof newPassword !== 'string' || newPassword.length < 6) {
      return res.status(400).json({ error: 'Mật khẩu mới phải có tối thiểu 6 ký tự' });
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanOtp = String(otp).trim();

    const user = await prisma.user.findUnique({
      where: { email: cleanEmail },
    });

    if (!user) {
      return res.status(404).json({ error: 'Người dùng không tồn tại' });
    }

    if (!user.resetOtp || user.resetOtp !== cleanOtp) {
      return res.status(400).json({ error: 'Mã OTP không chính xác' });
    }

    if (!user.resetOtpExpiry || new Date(user.resetOtpExpiry) < new Date()) {
      return res.status(400).json({ error: 'Mã OTP đã hết hạn, vui lòng yêu cầu gửi lại mã mới' });
    }

    // Mã hóa mật khẩu mới
    const hashedPassword = await bcrypt.hash(newPassword, 10);

    // Cập nhật CSDL và xóa OTP
    await prisma.user.update({
      where: { id: user.id },
      data: {
        password: hashedPassword,
        resetOtp: null,
        resetOtpExpiry: null,
      },
    });

    // Tạo thông báo cho người dùng
    await createNotification({
      userId: user.id,
      title: 'Đặt lại mật khẩu thành công',
      message: 'Mật khẩu tài khoản của bạn đã được đặt lại thành công qua mã xác thực OTP.',
    });

    res.json({ message: 'Đặt lại mật khẩu thành công! Bạn có thể đăng nhập bằng mật khẩu mới.' });
  } catch (error: any) {
    console.error('Error in resetPassword:', error);
    res.status(500).json({ error: 'Không thể đổi mật khẩu, vui lòng thử lại sau' });
  }
};

import { Request, Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { AuthRequest } from '../middleware/auth';
import * as XLSX from 'xlsx';
import multer from 'multer';
import path from 'path';
import fs from 'fs';

const prisma = new PrismaClient();

// Multer config – store file in memory (no disk write needed)
const storage = multer.memoryStorage();
export const uploadExcel = multer({
  storage,
  fileFilter: (_req, file, cb) => {
    const allowed = [
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'application/vnd.ms-excel',
      'application/octet-stream',
    ];
    if (allowed.includes(file.mimetype) || file.originalname.match(/\.(xlsx|xls)$/i)) {
      cb(null, true);
    } else {
      cb(new Error('Chỉ chấp nhận file Excel (.xlsx, .xls)'));
    }
  },
  limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB
}).single('file');

// Multer config for E-books (.pdf, .epub)
const ebookUploadDir = path.join(__dirname, '../../public/uploads/ebooks');
if (!fs.existsSync(ebookUploadDir)) {
  fs.mkdirSync(ebookUploadDir, { recursive: true });
}

const ebookStorage = multer.diskStorage({
  destination: (_req, _file, cb) => {
    cb(null, ebookUploadDir);
  },
  filename: (_req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    const uniqueName = `ebook-${Date.now()}-${Math.round(Math.random() * 1e6)}${ext}`;
    cb(null, uniqueName);
  }
});

export const uploadEbook = multer({
  storage: ebookStorage,
  fileFilter: (_req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    if (['.pdf', '.epub'].includes(ext) || file.mimetype === 'application/pdf' || file.mimetype === 'application/epub+zip') {
      cb(null, true);
    } else {
      cb(new Error('Chỉ chấp nhận định dạng file .pdf hoặc .epub'));
    }
  },
  limits: { fileSize: 100 * 1024 * 1024 } // 100 MB
}).single('file');

export const uploadEbookHandler = async (req: AuthRequest, res: Response) => {
  try {
    if (req.user?.role !== 'ADMIN') {
      return res.status(403).json({ error: 'Chỉ thủ thư/admin mới có quyền tải lên sách điện tử' });
    }
    if (!req.file) {
      return res.status(400).json({ error: 'Vui lòng chọn file PDF hoặc EPUB' });
    }

    const ebookUrl = `/uploads/ebooks/${req.file.filename}`;
    res.json({
      message: 'Tải lên sách điện tử thành công',
      ebookUrl,
      fileName: req.file.originalname,
      size: req.file.size
    });
  } catch (error: any) {
    console.error('Error uploading ebook:', error);
    res.status(500).json({ error: error.message || 'Không thể tải lên file e-book' });
  }
};

// Helper to format book for API & frontend compatibility
const formatBookResponse = (book: any) => {
  const items = book.items || [];
  const copies = items.length;
  const available = items.filter((item: any) => String(item.status).toUpperCase() === 'AVAILABLE').length;

  return {
    id: book.id,
    title: book.title,
    isbn: book.isbn,
    author: book.author?.name || '',
    category: book.category?.name || '',
    publisher: book.publisher?.name || '',
    publishedYear: book.publishedYear,
    pageCount: book.pageCount,
    language: book.language,
    description: book.description,
    coverImage: book.coverImage,
    ebookUrl: book.ebookUrl || null,
    copies,
    available,
    status: available > 0 ? 'Available' : 'Borrowed',
    items: items.map((item: any) => ({
      id: item.id,
      barcode: item.barcode,
      location: item.location,
      status: item.status
    })),
    authorId: book.authorId,
    categoryId: book.categoryId,
    publisherId: book.publisherId,
  };
};

export const getBooks = async (_req: Request, res: Response) => {
  try {
    const books = await prisma.book.findMany({
      include: {
        category: true,
        author: true,
        publisher: true,
        items: true,
      },
      orderBy: { id: 'asc' }
    });

    res.json(books.map(formatBookResponse));
  } catch (error) {
    console.error('Error fetching books:', error);
    res.status(500).json({ error: 'Không thể tải danh sách sách' });
  }
};

export const createBook = async (req: AuthRequest, res: Response) => {
  try {
    if (req.user?.role !== 'ADMIN') {
      return res.status(403).json({ error: 'Chỉ admin mới có quyền thêm sách' });
    }

    const {
      title,
      author,
      isbn,
      category,
      publisher,
      publishedYear,
      pageCount,
      language,
      description,
      coverImage,
      ebookUrl,
      copies = 1,
      available
    } = req.body;

    // Validate required fields
    if (!title || !author || !isbn || !category) {
      return res.status(400).json({
        error: 'Thiếu thông tin bắt buộc: title, author, isbn, category'
      });
    }

    const copiesNum = Number(copies) || 1;
    const availableNum = available !== undefined ? Number(available) : copiesNum;

    // Validate numbers
    if (copiesNum < 1) {
      return res.status(400).json({ error: 'Số lượng sách phải >= 1' });
    }
    if (availableNum < 0) {
      return res.status(400).json({ error: 'Số sách available phải >= 0' });
    }
    if (availableNum > copiesNum) {
      return res.status(400).json({ error: 'Số sách available không thể lớn hơn copies' });
    }

    const trimmedTitle = String(title).trim();
    const trimmedAuthor = String(author).trim();
    const trimmedIsbn = isbn ? String(isbn).trim() : '';
    const trimmedCategory = String(category).trim();
    const trimmedPublisher = publisher && String(publisher).trim() ? String(publisher).trim() : null;

    // Upsert Category
    const catRecord = await prisma.category.upsert({
      where: { name: trimmedCategory },
      update: {},
      create: { name: trimmedCategory }
    });

    // Upsert Author
    const authorRecord = await prisma.author.upsert({
      where: { name: trimmedAuthor },
      update: {},
      create: { name: trimmedAuthor }
    });

    // Upsert Publisher if provided
    let publisherRecord = null;
    if (trimmedPublisher) {
      publisherRecord = await prisma.publisher.upsert({
        where: { name: trimmedPublisher },
        update: {},
        create: { name: trimmedPublisher }
      });
    }

    // --- TỰ ĐỘNG GỘP KHO (Smart Inventory Merge) ---
    // Kiểm tra xem sách đã tồn tại chưa: Ưu tiên trùng ISBN (nếu có) HOẶC trùng cả title và authorId
    const existingBook = await prisma.book.findFirst({
      where: {
        OR: [
          ...(trimmedIsbn ? [{ isbn: trimmedIsbn }] : []),
          {
            title: trimmedTitle,
            authorId: authorRecord.id
          }
        ]
      },
      include: {
        category: true,
        author: true,
        publisher: true,
        items: true,
      }
    });

    // =========================================================================
    // KỊCH BẢN 2: Sách đã tồn tại trong hệ thống -> TỰ ĐỘNG CỘNG GỘP KHO (MERGE)
    // =========================================================================
    if (existingBook) {
      const cleanIsbn = String(existingBook.isbn).replace(/[^0-9]/g, '').slice(-6) || 'BOOK';

      const updatedBookWithRelations = await prisma.$transaction(async (tx) => {
        let indexCounter = existingBook.items.length + 1;
        for (let i = 0; i < copiesNum; i++) {
          let candidateBarcode = `BC-${cleanIsbn}-${String(indexCounter).padStart(3, '0')}`;
          // Kiểm tra để barcode tuyệt đối không bao giờ bị trùng lặp
          while (await tx.bookItem.findUnique({ where: { barcode: candidateBarcode } })) {
            indexCounter++;
            candidateBarcode = `BC-${cleanIsbn}-${String(indexCounter).padStart(3, '0')}`;
          }

          await tx.bookItem.create({
            data: {
              bookId: existingBook.id,
              barcode: candidateBarcode,
              location: 'Khu A - Kệ 1',
              status: 'AVAILABLE' // Luôn sẵn sàng trên kệ
            }
          });
          indexCounter++;
        }

        return await tx.book.findUnique({
          where: { id: existingBook.id },
          include: {
            category: true,
            author: true,
            publisher: true,
            items: true,
          }
        });
      });

      return res.status(200).json({
        message: `Sách đã tồn tại. Tự động cộng gộp thêm ${copiesNum} bản sao vào kho`,
        isMerged: true,
        ...formatBookResponse(updatedBookWithRelations)
      });
    }

    // =========================================================================
    // KỊCH BẢN 1: Chưa tồn tại -> TẠO MỚI HOÀN TOÀN BẢN GHI BOOK VÀ BẢN SAO
    // =========================================================================
    const cleanIsbn = String(trimmedIsbn).replace(/[^0-9]/g, '').slice(-6) || 'BOOK';

    const createdBookWithRelations = await prisma.$transaction(async (tx) => {
      const newBook = await tx.book.create({
        data: {
          title: trimmedTitle,
          isbn: trimmedIsbn,
          categoryId: catRecord.id,
          authorId: authorRecord.id,
          publisherId: publisherRecord ? publisherRecord.id : null,
          publishedYear: publishedYear ? String(publishedYear) : null,
          pageCount: pageCount ? Number(pageCount) : null,
          language: language ? String(language) : 'Tiếng Việt',
          description: description || null,
          coverImage: coverImage || null,
          ebookUrl: ebookUrl ? String(ebookUrl).trim() : null,
        }
      });

      let indexCounter = 1;
      for (let i = 0; i < copiesNum; i++) {
        let candidateBarcode = `BC-${cleanIsbn}-${String(indexCounter).padStart(3, '0')}`;
        while (await tx.bookItem.findUnique({ where: { barcode: candidateBarcode } })) {
          indexCounter++;
          candidateBarcode = `BC-${cleanIsbn}-${String(indexCounter).padStart(3, '0')}`;
        }

        await tx.bookItem.create({
          data: {
            bookId: newBook.id,
            barcode: candidateBarcode,
            location: 'Khu A - Kệ 1',
            status: 'AVAILABLE' // Luôn sẵn sàng trên kệ
          }
        });
        indexCounter++;
      }

      return await tx.book.findUnique({
        where: { id: newBook.id },
        include: {
          category: true,
          author: true,
          publisher: true,
          items: true,
        }
      });
    });

    return res.status(201).json({
      message: `Đã thêm sách mới và ${copiesNum} bản sao vào kho`,
      isMerged: false,
      ...formatBookResponse(createdBookWithRelations)
    });
  } catch (error: any) {
    console.error('Error creating book:', error);
    if (error.code === 'P2002') {
      res.status(400).json({ error: 'ISBN đã tồn tại' });
    } else {
      res.status(500).json({ error: 'Không thể tạo sách mới' });
    }
  }
};

export const updateBook = async (req: AuthRequest, res: Response) => {
  try {
    if (req.user?.role !== 'ADMIN') {
      return res.status(403).json({ error: 'Chỉ admin mới có quyền sửa sách' });
    }

    const { id } = req.params;
    const bookId = parseInt(id as string);
    if (isNaN(bookId)) {
      return res.status(400).json({ error: 'ID sách không hợp lệ' });
    }

    const existingBook = await prisma.book.findUnique({
      where: { id: bookId },
      include: { items: true }
    });

    if (!existingBook) {
      return res.status(404).json({ error: 'Không tìm thấy sách' });
    }

    const {
      title,
      author,
      isbn,
      category,
      publisher,
      publishedYear,
      pageCount,
      language,
      description,
      coverImage,
      ebookUrl,
      copies
    } = req.body;

    const updateData: any = {};
    if (title !== undefined) updateData.title = String(title).trim();
    if (isbn !== undefined) updateData.isbn = String(isbn).trim();
    if (publishedYear !== undefined) updateData.publishedYear = publishedYear ? String(publishedYear) : null;
    if (pageCount !== undefined) updateData.pageCount = pageCount ? Number(pageCount) : null;
    if (language !== undefined) updateData.language = language ? String(language) : null;
    if (description !== undefined) updateData.description = description;
    if (coverImage !== undefined) updateData.coverImage = coverImage;
    if (ebookUrl !== undefined) updateData.ebookUrl = ebookUrl ? String(ebookUrl).trim() : null;

    if (category) {
      const cat = await prisma.category.upsert({
        where: { name: String(category).trim() },
        update: {},
        create: { name: String(category).trim() }
      });
      updateData.categoryId = cat.id;
    }

    if (author) {
      const auth = await prisma.author.upsert({
        where: { name: String(author).trim() },
        update: {},
        create: { name: String(author).trim() }
      });
      updateData.authorId = auth.id;
    }

    if (publisher !== undefined) {
      if (publisher) {
        const pub = await prisma.publisher.upsert({
          where: { name: String(publisher).trim() },
          update: {},
          create: { name: String(publisher).trim() }
        });
        updateData.publisherId = pub.id;
      } else {
        updateData.publisherId = null;
      }
    }

    await prisma.book.update({
      where: { id: bookId },
      data: updateData
    });

    // If copies count changed, adjust BookItems
    if (copies !== undefined && Number(copies) > 0) {
      const currentCount = existingBook.items.length;
      const targetCount = Number(copies);
      if (targetCount > currentCount) {
        const cleanIsbn = (isbn || existingBook.isbn).replace(/[^0-9]/g, '').slice(-6);
        for (let i = currentCount; i < targetCount; i++) {
          await prisma.bookItem.create({
            data: {
              bookId,
              barcode: `BC-${cleanIsbn}-${String(i + 1).padStart(3, '0')}`,
              location: 'Khu A - Kệ 1',
              status: 'AVAILABLE'
            }
          });
        }
      }
    }

    const updatedBookWithRelations = await prisma.book.findUnique({
      where: { id: bookId },
      include: {
        category: true,
        author: true,
        publisher: true,
        items: true,
      }
    });

    res.json(formatBookResponse(updatedBookWithRelations));
  } catch (error: any) {
    console.error('Error updating book:', error);
    if (error.code === 'P2025') {
      res.status(404).json({ error: 'Không tìm thấy sách' });
    } else if (error.code === 'P2002') {
      res.status(400).json({ error: 'ISBN đã tồn tại' });
    } else {
      res.status(500).json({ error: 'Không thể cập nhật sách' });
    }
  }
};

export const deleteBook = async (req: AuthRequest, res: Response) => {
  try {
    if (req.user?.role !== 'ADMIN') {
      return res.status(403).json({ error: 'Chỉ admin mới có quyền xóa sách' });
    }

    const { id } = req.params;
    const bookId = parseInt(id as string);
    if (isNaN(bookId)) {
      return res.status(400).json({ error: 'ID sách không hợp lệ' });
    }

    // Check if any physical copy is currently borrowed
    const borrowedCount = await prisma.bookItem.count({
      where: {
        bookId,
        status: 'BORROWED'
      }
    });

    if (borrowedCount > 0) {
      return res.status(400).json({
        error: `Không thể xóa sách này vì đang có ${borrowedCount} cuốn đang được mượn`
      });
    }

    // Cascade delete related records
    const items = await prisma.bookItem.findMany({
      where: { bookId },
      select: { id: true }
    });
    const itemIds = items.map(i => i.id);

    if (itemIds.length > 0) {
      await prisma.loan.deleteMany({
        where: { bookItemId: { in: itemIds } }
      });
      await prisma.bookItem.deleteMany({
        where: { bookId }
      });
    }

    await prisma.reservation.deleteMany({
      where: { bookId }
    });

    await prisma.book.delete({ where: { id: bookId } });
    res.json({ message: 'Xóa sách thành công' });
  } catch (error: any) {
    console.error('Error deleting book:', error);
    if (error.code === 'P2025') {
      res.status(404).json({ error: 'Không tìm thấy sách' });
    } else {
      res.status(500).json({ error: 'Không thể xóa sách' });
    }
  }
};

// =============================================
// Import Books from Excel
// =============================================
export const importBooks = async (req: AuthRequest, res: Response) => {
  try {
    if (req.user?.role !== 'ADMIN') {
      return res.status(403).json({ error: 'Chỉ admin mới có quyền import sách' });
    }

    if (!req.file) {
      return res.status(400).json({ error: 'Vui lòng chọn file Excel để tải lên' });
    }

    // Read the uploaded Excel file from memory buffer
    const workbook = XLSX.read(req.file.buffer, { type: 'buffer' });
    const sheetName = workbook.SheetNames[0];
    if (!sheetName) {
      return res.status(400).json({ error: 'File Excel không có sheet nào' });
    }

    const rows: any[] = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);
    if (rows.length === 0) {
      return res.status(400).json({ error: 'File Excel trống, không có dữ liệu để import' });
    }

    // Column name mapping – supports both Vietnamese and English headers
    const colMap: Record<string, string> = {
      'tiêu đề': 'title', 'tieu de': 'title', 'title': 'title', 'tên sách': 'title', 'ten sach': 'title',
      'tác giả': 'author', 'tac gia': 'author', 'author': 'author',
      'isbn': 'isbn', 'mã isbn': 'isbn', 'ma isbn': 'isbn',
      'thể loại': 'category', 'the loai': 'category', 'category': 'category',
      'số lượng': 'copies', 'so luong': 'copies', 'copies': 'copies', 'số lượng bản sao': 'copies', 'so luong ban sao': 'copies',
      'nhà xuất bản': 'publisher', 'nha xuat ban': 'publisher', 'publisher': 'publisher', 'nxb': 'publisher',
      'năm xuất bản': 'publishedYear', 'nam xuat ban': 'publishedYear', 'publishedyear': 'publishedYear', 'year': 'publishedYear', 'năm xb': 'publishedYear',
      'số trang': 'pageCount', 'so trang': 'pageCount', 'pagecount': 'pageCount', 'pages': 'pageCount',
      'ngôn ngữ': 'language', 'ngon ngu': 'language', 'language': 'language',
      'mô tả': 'description', 'mo ta': 'description', 'description': 'description',
      'ảnh bìa': 'coverImage', 'anh bia': 'coverImage', 'coverimage': 'coverImage', 'cover': 'coverImage',
    };

    const normalizeKey = (key: string): string => {
      const normalized = key.trim().toLowerCase();
      return colMap[normalized] || normalized;
    };

    const imported: { title: string; isbn: string; copies: number }[] = [];
    const skipped: { row: number; title: string; isbn: string; reason: string }[] = [];
    const seenIsbnsInFile = new Set<string>();
    let totalCopiesCreated = 0;

    for (let i = 0; i < rows.length; i++) {
      const raw = rows[i];
      const rowNum = i + 2; // Excel row (1-indexed header + 1)

      // Map raw keys to normalized keys
      const row: Record<string, any> = {};
      for (const key of Object.keys(raw)) {
        row[normalizeKey(key)] = raw[key];
      }

      const title = row.title ? String(row.title).trim() : '';
      const author = row.author ? String(row.author).trim() : '';
      const isbn = row.isbn ? String(row.isbn).trim() : '';
      const category = row.category ? String(row.category).trim() : '';
      const copies = Math.max(1, parseInt(row.copies) || 1);

      if (!title || !author || !isbn || !category) {
        skipped.push({
          row: rowNum,
          title: title || '(Chưa có tiêu đề)',
          isbn: isbn || '(Thiếu ISBN)',
          reason: 'Thiếu trường bắt buộc (Tiêu đề, Tác giả, ISBN, hoặc Thể loại)'
        });
        continue;
      }

      // Check duplicate within the uploaded file
      const normalizedIsbn = isbn.replace(/\s+/g, '');
      if (seenIsbnsInFile.has(normalizedIsbn)) {
        skipped.push({
          row: rowNum,
          title,
          isbn,
          reason: `Trùng lặp mã ISBN "${isbn}" với một dòng trước đó trong file Excel`
        });
        continue;
      }
      seenIsbnsInFile.add(normalizedIsbn);

      try {
        // Check for duplicate ISBN in Database
        const existingBook = await prisma.book.findUnique({ where: { isbn } });
        if (existingBook) {
          skipped.push({
            row: rowNum,
            title,
            isbn,
            reason: `Trùng mã ISBN "${isbn}" với sách đã có trong thư viện: "${existingBook.title}"`
          });
          continue;
        }

        // Upsert Category
        const catRecord = await prisma.category.upsert({
          where: { name: category },
          update: {},
          create: { name: category }
        });

        // Upsert Author
        const authorRecord = await prisma.author.upsert({
          where: { name: author },
          update: {},
          create: { name: author }
        });

        // Upsert Publisher
        let publisherRecord = null;
        const publisherName = row.publisher ? String(row.publisher).trim() : '';
        if (publisherName) {
          publisherRecord = await prisma.publisher.upsert({
            where: { name: publisherName },
            update: {},
            create: { name: publisherName }
          });
        }

        // Prisma Transaction: Atomically create Book and all BookItems with status: "AVAILABLE"
        await prisma.$transaction(async (tx) => {
          const createdBook = await tx.book.create({
            data: {
              title,
              isbn,
              categoryId: catRecord.id,
              authorId: authorRecord.id,
              publisherId: publisherRecord ? publisherRecord.id : null,
              publishedYear: row.publishedYear ? String(row.publishedYear) : null,
              pageCount: row.pageCount ? Number(row.pageCount) : null,
              language: row.language ? String(row.language).trim() : 'Tiếng Việt',
              description: row.description ? String(row.description).trim() : null,
              coverImage: row.coverImage ? String(row.coverImage).trim() : null,
            }
          });

          // Generate physical copies (BookItems) - 100% AVAILABLE (No ghost copies)
          const cleanIsbn = isbn.replace(/[^0-9]/g, '').slice(-6) || String(createdBook.id);
          for (let j = 0; j < copies; j++) {
            await tx.bookItem.create({
              data: {
                bookId: createdBook.id,
                barcode: `BC-${cleanIsbn}-${String(j + 1).padStart(3, '0')}`,
                location: 'Khu A - Kệ 1',
                status: 'AVAILABLE'
              }
            });
          }
        });

        totalCopiesCreated += copies;
        imported.push({ title, isbn, copies });
      } catch (err: any) {
        skipped.push({
          row: rowNum,
          title,
          isbn,
          reason: `Lỗi xử lý cơ sở dữ liệu: ${err.message || 'Lỗi không xác định'}`
        });
      }
    }

    // Audit log
    if (imported.length > 0) {
      await prisma.auditLog.create({
        data: {
          action: 'IMPORT_EXCEL',
          adminId: req.user!.userId,
          details: JSON.stringify({
            fileName: req.file.originalname,
            totalRows: rows.length,
            importedCount: imported.length,
            totalCopies: totalCopiesCreated,
            skippedCount: skipped.length,
          })
        }
      });
    }

    const summaryMessage = skipped.length > 0
      ? `Đã thêm thành công ${imported.length} đầu sách (${totalCopiesCreated} cuốn), bỏ qua ${skipped.length} cuốn do trùng mã hoặc lỗi dữ liệu`
      : `Đã thêm thành công toàn bộ ${imported.length} đầu sách (${totalCopiesCreated} cuốn bản sao)!`;

    res.json({
      success: true,
      message: summaryMessage,
      importedCount: imported.length,
      totalCopiesCreated,
      skippedCount: skipped.length,
      imported,
      skipped,
      totalRows: rows.length,
    });
  } catch (error: any) {
    console.error('Error importing books:', error);
    res.status(500).json({ error: error.message || 'Không thể import sách từ file Excel' });
  }
};

