export const getBookRecommendations = async (req: AuthRequest, res: Response) => {
  try {
    const userId = req.user?.userId;

    let userLoans: any[] = [];
    if (userId) {
      userLoans = await prisma.loan.findMany({
        where: { userId },
        include: {
          bookItem: {
            include: {
              book: {
                include: {
                  category: true,
                  author: true,
                }
              }
            }
          }
        }
      });
    }

    const borrowedBookIds = new Set<number>();
    const categoryFrequency: Record<number, { count: number; name: string }> = {};
    const authorFrequency: Record<number, { count: number; name: string }> = {};

    for (const loan of userLoans) {
      const book = loan.bookItem?.book;
      if (!book) continue;
      borrowedBookIds.add(book.id);

      if (book.categoryId) {
        if (!categoryFrequency[book.categoryId]) {
          categoryFrequency[book.categoryId] = { count: 0, name: book.category?.name || '' };
        }
        categoryFrequency[book.categoryId].count++;
      }

      if (book.authorId) {
        if (!authorFrequency[book.authorId]) {
          authorFrequency[book.authorId] = { count: 0, name: book.author?.name || '' };
        }
        authorFrequency[book.authorId].count++;
      }
    }

    const sortedCategories = Object.entries(categoryFrequency).sort((a, b) => b[1].count - a[1].count);
    const topCategory = sortedCategories.length > 0 ? { id: Number(sortedCategories[0][0]), ...sortedCategories[0][1] } : null;

    const sortedAuthors = Object.entries(authorFrequency).sort((a, b) => b[1].count - a[1].count);
    const topAuthor = sortedAuthors.length > 0 ? { id: Number(sortedAuthors[0][0]), ...sortedAuthors[0][1] } : null;

    let candidateBooks: any[] = [];
    let recommendationType: 'PERSONALIZED' | 'TRENDING' = 'PERSONALIZED';
    let recommendationReason = '';

    if (topCategory || topAuthor) {
      const orConditions: any[] = [];
      if (topCategory) {
        orConditions.push({ categoryId: topCategory.id });
      }
      if (topAuthor) {
        orConditions.push({ authorId: topAuthor.id });
      }

      candidateBooks = await prisma.book.findMany({
        where: {
          AND: [
            { id: { notIn: Array.from(borrowedBookIds) } },
            { OR: orConditions }
          ]
        },
        include: {
          category: true,
          author: true,
          publisher: true,
          items: true
        },
        take: 10
      });

      if (candidateBooks.length > 0) {
        if (topCategory && topAuthor) {
          recommendationReason = `Dựa trên sở thích đọc sách: Thể loại "${topCategory.name}" & Tác giả "${topAuthor.name}"`;
        } else if (topCategory) {
          recommendationReason = `Dựa trên thể loại bạn thường mượn: "${topCategory.name}"`;
        } else if (topAuthor) {
          recommendationReason = `Dựa trên tác giả bạn yêu thích: "${topAuthor.name}"`;
        }
      }
    }

    // Step 3: Fallback or supplement with Trending Books if user is new or candidate count is small (< 6)
    if (candidateBooks.length < 6) {
      // Calculate borrow count per book
      const allLoans = await prisma.loan.findMany({
        select: {
          bookItem: {
            select: { bookId: true }
          }
        }
      });

      const bookBorrowCounts = new Map<number, number>();
      for (const l of allLoans) {
        const bId = l.bookItem?.bookId;
        if (bId) {
          bookBorrowCounts.set(bId, (bookBorrowCounts.get(bId) || 0) + 1);
        }
      }

      const excludeIds = new Set<number>([
        ...Array.from(borrowedBookIds),
        ...candidateBooks.map((b: any) => b.id)
      ]);

      const trendingPool = await prisma.book.findMany({
        where: {
          id: { notIn: Array.from(excludeIds) }
        },
        include: {
          category: true,
          author: true,
          publisher: true,
          items: true
        }
      });

      // Sort trending pool: most borrowed first, then most available copies
      trendingPool.sort((a, b) => {
        const countA = bookBorrowCounts.get(a.id) || 0;
        const countB = bookBorrowCounts.get(b.id) || 0;
        if (countB !== countA) return countB - countA;
        const availA = a.items?.filter((i: any) => i.status === 'AVAILABLE').length || 0;
        const availB = b.items?.filter((i: any) => i.status === 'AVAILABLE').length || 0;
        return availB - availA;
      });

      const needed = 10 - candidateBooks.length;
      const additionalTrending = trendingPool.slice(0, needed);

      if (candidateBooks.length === 0) {
        recommendationType = 'TRENDING';
        recommendationReason = 'Top những cuốn sách thịnh hành được mượn nhiều nhất tại thư viện';
        candidateBooks = additionalTrending;
      } else {
        candidateBooks = [...candidateBooks, ...additionalTrending];
      }
    }

    const formattedBooks = candidateBooks.map((book: any) => {
      const isPersonalized =
        recommendationType === 'PERSONALIZED' &&
        ((topCategory && book.categoryId === topCategory.id) || (topAuthor && book.authorId === topAuthor.id));

      const badge = isPersonalized ? 'Phù hợp với bạn' : 'Thịnh hành';
      const reason = isPersonalized
        ? (book.categoryId === topCategory?.id ? `Cùng thể loại ${topCategory?.name}` : `Tác giả ${topAuthor?.name}`)
        : 'Được nhiều bạn đọc yêu thích';

      return {
        ...formatBookResponse(book),
        recommendationBadge: badge,
        recommendationReason: reason
      };
    });

    res.json({
      success: true,
      type: recommendationType,
      reason: recommendationReason,
      books: formattedBooks
    });
  } catch (error: any) {
    console.error('Error fetching book recommendations:', error);
    res.status(500).json({ error: error.message || 'Không thể lấy danh sách gợi ý sách' });
  }
};

import { Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { AuthRequest } from '../middleware/auth';

const prisma = new PrismaClient();

/**
 * GET /api/inventory/expected
 * Lấy danh sách tất cả các bản sao (BookItem) đang có trạng thái AVAILABLE
 * (nghĩa là đang có mặt thực tế trên kệ sách theo hệ thống).
 */
export const getExpectedInventory = async (req: AuthRequest, res: Response) => {
  try {
    const expectedItems = await prisma.bookItem.findMany({
      where: {
        status: { in: ['AVAILABLE', 'Available'] }
      },
      include: {
        book: {
          include: {
            category: true,
            author: true
          }
        }
      },
      orderBy: { barcode: 'asc' }
    });

    const formatted = expectedItems.map((item) => ({
      id: item.id,
      barcode: item.barcode,
      location: item.location || 'Khu A - Kệ 1',
      status: item.status,
      bookId: item.bookId,
      bookTitle: item.book?.title || 'Chưa có tiêu đề',
      isbn: item.book?.isbn || '',
      author: item.book?.author?.name || '',
      category: item.book?.category?.name || '',
      coverImage: item.book?.coverImage
    }));

    res.json({
      total: formatted.length,
      items: formatted
    });
  } catch (error: any) {
    console.error('Error fetching expected inventory:', error);
    res.status(500).json({ error: error.message || 'Không thể lấy danh sách kho dự kiến' });
  }
};

/**
 * POST /api/inventory/verify
 * Đối chiếu danh sách mã vạch quét được trên kệ (scannedBarcodes) với CSDL.
 * Trả về 3 nhóm:
 * 1. Sách hợp lệ (matched): Có trong CSDL báo AVAILABLE và được quét trên kệ.
 * 2. Sách bị thiếu (missing): CSDL báo AVAILABLE nhưng không quét được trên kệ.
 * 3. Sách bất thường (anomalous): Quét được trên kệ nhưng CSDL báo BORROWED, LOST, DAMAGED hoặc không tồn tại.
 */
export const verifyInventory = async (req: AuthRequest, res: Response) => {
  try {
    const { scannedBarcodes = [] } = req.body;

    if (!Array.isArray(scannedBarcodes)) {
      return res.status(400).json({ error: 'scannedBarcodes phải là một mảng chuỗi mã vạch' });
    }

    // Chuẩn hóa và lọc trùng mã vạch quét được
    const uniqueScanned = Array.from(
      new Set(
        scannedBarcodes
          .map((b: any) => String(b || '').trim().toUpperCase())
          .filter((b: string) => b.length > 0)
      )
    );

    // Lấy toàn bộ BookItem trong hệ thống kèm thông tin sách
    const allItems = await prisma.bookItem.findMany({
      include: {
        book: {
          include: {
            category: true,
            author: true
          }
        }
      }
    });

    // Tạo Map tra cứu theo barcode in hoa
    const itemMap = new Map<string, typeof allItems[0]>();
    allItems.forEach((item) => {
      itemMap.set(item.barcode.toUpperCase(), item);
    });

    const scannedSet = new Set(uniqueScanned);

    const matched: any[] = [];
    const anomalous: any[] = [];
    const missing: any[] = [];

    // 1. Phân loại các mã vạch quét được
    for (const barcode of uniqueScanned) {
      const item = itemMap.get(barcode);

      if (!item) {
        // Mã vạch hoàn toàn không có trong cơ sở dữ liệu
        anomalous.push({
          barcode,
          issueType: 'NOT_FOUND',
          reason: 'Mã vạch lạ, không tồn tại trong hệ thống thư viện',
          bookTitle: 'Không xác định',
          author: 'N/A',
          location: 'Chưa xếp kệ',
          dbStatus: 'KHÔNG TỒN TẠI'
        });
      } else if (item.status === 'AVAILABLE' || item.status === 'Available') {
        // Hợp lệ: Sách có trong DB và đang Available
        matched.push({
          id: item.id,
          barcode: item.barcode,
          bookTitle: item.book?.title || 'Chưa có tiêu đề',
          author: item.book?.author?.name || '',
          category: item.book?.category?.name || '',
          location: item.location || 'Khu A - Kệ 1',
          status: item.status,
          coverImage: item.book?.coverImage
        });
      } else {
        // Bất thường: Sách có trong DB nhưng trạng thái khác AVAILABLE (BORROWED, LOST, DAMAGED...)
        let reason = 'Trạng thái bất thường';
        if (item.status === 'BORROWED') {
          reason = 'Sách đang ghi nhận BORROWED (đang cho độc giả mượn) nhưng lại xuất hiện trên kệ';
        } else if (item.status === 'LOST') {
          reason = 'Sách đã báo LOST (mất) nhưng lại được tìm thấy trên giá sách';
        } else if (item.status === 'DAMAGED') {
          reason = 'Sách ghi nhận DAMAGED (hỏng hóc/cách ly) nhưng vẫn nằm trên kệ lưu thông';
        }

        anomalous.push({
          id: item.id,
          barcode: item.barcode,
          issueType: item.status,
          reason,
          bookTitle: item.book?.title || 'Chưa có tiêu đề',
          author: item.book?.author?.name || '',
          category: item.book?.category?.name || '',
          location: item.location || 'Khu A - Kệ 1',
          dbStatus: item.status,
          coverImage: item.book?.coverImage
        });
      }
    }

    // 2. Tìm sách bị thiếu (Có trong DB trạng thái AVAILABLE nhưng thủ thư không quét được)
    allItems.forEach((item) => {
      const isAvailable = item.status === 'AVAILABLE' || item.status === 'Available';
      if (isAvailable && !scannedSet.has(item.barcode.toUpperCase())) {
        missing.push({
          id: item.id,
          barcode: item.barcode,
          bookTitle: item.book?.title || 'Chưa có tiêu đề',
          author: item.book?.author?.name || '',
          category: item.book?.category?.name || '',
          location: item.location || 'Khu A - Kệ 1',
          status: item.status,
          coverImage: item.book?.coverImage
        });
      }
    });

    const totalExpected = matched.length + missing.length;
    const accuracyRate = totalExpected > 0 ? ((matched.length / totalExpected) * 100).toFixed(1) : '100.0';

    // 3. Ghi Audit Log cho đợt kiểm kê
    try {
      await prisma.auditLog.create({
        data: {
          action: 'INVENTORY_CHECK',
          adminId: req.user?.userId || 1,
          details: JSON.stringify({
            totalExpected,
            totalScanned: uniqueScanned.length,
            matchedCount: matched.length,
            missingCount: missing.length,
            anomalousCount: anomalous.length,
            accuracyRate: `${accuracyRate}%`,
            checkedAt: new Date().toISOString()
          })
        }
      });
    } catch (e) {
      console.error('AuditLog error:', e);
    }

    res.json({
      summary: {
        totalExpected,
        totalScanned: uniqueScanned.length,
        matchedCount: matched.length,
        missingCount: missing.length,
        anomalousCount: anomalous.length,
        accuracyRate,
        checkedAt: new Date().toISOString()
      },
      matched,
      missing,
      anomalous
    });
  } catch (error: any) {
    console.error('Error verifying inventory:', error);
    res.status(500).json({ error: error.message || 'Lỗi khi đối chiếu kiểm kê kho sách' });
  }
};

import { Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { AuthRequest } from '../middleware/auth';
import { createNotification } from '../services/notificationService';
import { calculateDueDate, calculateFine, calculateRenewedDueDate, daysUntilDue, FINE_PER_DAY } from '../utils/loanRules';

const prisma = new PrismaClient();

// =============================================
// State Machine Constants
// =============================================
export const BOOK_ITEM_STATUS = {
    AVAILABLE: 'AVAILABLE',
    BORROWED: 'BORROWED',
    LOST: 'LOST',
    DAMAGED: 'DAMAGED'
} as const;

export const LOAN_STATUS = {
    ACTIVE: 'ACTIVE',
    OVERDUE: 'OVERDUE',
    LOST_PENDING_PAYMENT: 'LOST_PENDING_PAYMENT',
    COMPLETED: 'COMPLETED'
} as const;

export const RENEWAL_STATUS = {
    NONE: 'NONE',
    PENDING: 'PENDING',
    APPROVED: 'APPROVED',
    REJECTED: 'REJECTED'
} as const;

// Helper to compute display status and shape response for frontend compatibility
export const formatLoanResponse = (loan: any, availableCopies?: number) => {
    let uiStatus = 'On Time';

    if (loan.status === LOAN_STATUS.LOST_PENDING_PAYMENT || loan.status === 'LOST' || loan.status === 'Lost') {
        uiStatus = 'Lost';
    } else if (loan.status === LOAN_STATUS.COMPLETED || loan.status === 'RETURNED' || loan.status === 'Returned') {
        uiStatus = 'Returned';
    } else if (loan.status === LOAN_STATUS.OVERDUE || loan.status === 'Overdue') {
        uiStatus = 'Overdue';
    } else {
        const diffDays = daysUntilDue(new Date(loan.dueDate), new Date());
        if (diffDays < 0) {
            uiStatus = 'Overdue';
        } else if (diffDays <= 2) {
            uiStatus = 'Due Soon';
        } else {
            uiStatus = 'On Time';
        }
    }

    const diffDays = daysUntilDue(new Date(loan.dueDate), new Date());

    let calculatedFine = loan.fineAmount || 0;
    if (loan.compensationAmount && loan.compensationAmount > 0 && !loan.isFinePaid) {
        calculatedFine = loan.compensationAmount;
    } else if (!loan.isFinePaid && (loan.status === LOAN_STATUS.OVERDUE || diffDays < 0)) {
        if (!loan.fineAmount || loan.fineAmount === 0) {
            calculatedFine = Math.max(0, Math.abs(diffDays) * FINE_PER_DAY);
        }
    }

    const book = loan.bookItem?.book;
    const computedAvailable = availableCopies !== undefined
        ? availableCopies
        : (book?.items ? book.items.filter((i: any) => String(i.status).toUpperCase() === BOOK_ITEM_STATUS.AVAILABLE).length : undefined);

    return {
        id: loan.id,
        userId: loan.userId,
        bookItemId: loan.bookItemId,
        bookId: book ? book.id : null,
        borrowDate: loan.borrowDate,
        dueDate: loan.dueDate,
        returnDate: loan.returnDate,
        status: uiStatus,
        rawStatus: loan.status,
        fineAmount: calculatedFine,
        compensationAmount: loan.compensationAmount || 0,
        isFinePaid: Boolean(loan.isFinePaid),
        finePaidAt: loan.finePaidAt,
        paymentMethod: loan.paymentMethod,
        paymentTransactionId: loan.paymentTransactionId,
        renewalStatus: loan.renewalStatus || RENEWAL_STATUS.NONE,
        available: computedAvailable,
        availableCopies: computedAvailable,
        book: book ? {
            id: book.id,
            title: book.title,
            isbn: book.isbn,
            author: book.author?.name || '',
            category: book.category?.name || '',
            coverImage: book.coverImage,
            available: computedAvailable,
            copies: book.items?.length
        } : null,
        bookItem: loan.bookItem ? {
            id: loan.bookItem.id,
            barcode: loan.bookItem.barcode,
            location: loan.bookItem.location,
            status: loan.bookItem.status
        } : null,
        user: loan.user ? {
            id: loan.user.id,
            name: loan.user.name,
            email: loan.user.email
        } : (loan.userId ? {
            id: loan.userId,
            name: 'Độc giả',
            email: ''
        } : undefined)
    };
};

/**
 * Kiểm duyệt rủi ro mượn sách:
 * 1. Chặn mượn nếu User có isBlacklisted == true
 * 2. Chặn mượn nếu User đang có phiếu mượn quá hạn hoặc chưa thanh toán nợ phạt
 * 3. Giới hạn số lượng sách đang mượn theo hạng thành viên (STANDARD: 5, PREMIUM: 10, LECTURER: 15)
 */
export const validateBorrowRisk = async (userId: number): Promise<{ allowed: boolean; error?: string; status?: number }> => {
    const user = await prisma.user.findUnique({
        where: { id: userId },
        include: {
            loans: {
                where: {
                    OR: [
                        { returnDate: null },
                        { status: LOAN_STATUS.OVERDUE },
                        { status: LOAN_STATUS.LOST_PENDING_PAYMENT },
                        { isFinePaid: false, fineAmount: { gt: 0 } },
                        { isFinePaid: false, compensationAmount: { gt: 0 } }
                    ]
                },
                include: {
                    bookItem: {
                        include: { book: true }
                    }
                }
            }
        }
    });

    if (!user) {
        return { allowed: false, error: 'Không tìm thấy thông tin người dùng', status: 404 };
    }

    // 1. Kiểm tra Blacklist
    if (user.isBlacklisted) {
        return {
            allowed: false,
            error: 'Tài khoản của bạn đã bị đưa vào danh sách hạn chế (Blacklist). Bạn không thể mượn sách mới, vui lòng liên hệ thủ thư để được mở khóa!',
            status: 403
        };
    }

    // 2. Kiểm tra sách quá hạn hoặc nợ phạt chưa thanh toán
    const now = new Date();
    const blockingLoans = user.loans.filter(loan => {
        if (loan.status === LOAN_STATUS.OVERDUE || loan.status === LOAN_STATUS.LOST_PENDING_PAYMENT) return true;
        if (!loan.returnDate && new Date(loan.dueDate) < now) return true;
        if (!loan.isFinePaid && ((loan.fineAmount && loan.fineAmount > 0) || (loan.compensationAmount && loan.compensationAmount > 0))) return true;
        return false;
    });

    if (blockingLoans.length > 0) {
        const blockingTitles = blockingLoans
            .map(l => `"${l.bookItem?.book?.title || 'Sách'}"`)
            .slice(0, 3)
            .join(', ');
        return {
            allowed: false,
            error: `Độc giả đang có ${blockingLoans.length} phiếu mượn quá hạn hoặc chưa hoàn tất nộp phạt (${blockingTitles}${blockingLoans.length > 3 ? '...' : ''}). Vui lòng thanh toán phạt hoặc trả sách trước khi mượn tiếp!`,
            status: 400
        };
    }

    // 3. Giới hạn số lượng sách đang mượn đồng thời theo hạng thành viên
    const activeBorrowCount = user.loans.filter(l => l.returnDate === null).length;
    const tier = (user.membershipTier || 'STANDARD').toUpperCase();
    let maxAllowed = 5; // STANDARD mặc định 5 cuốn
    if (tier === 'PREMIUM') {
        maxAllowed = 10; // PREMIUM tối đa 10 cuốn
    } else if (tier === 'LECTURER') {
        maxAllowed = 15; // LECTURER tối đa 15 cuốn
    }

    if (activeBorrowCount >= maxAllowed) {
        return {
            allowed: false,
            error: `Độc giả đã đạt giới hạn mượn tối đa (${activeBorrowCount}/${maxAllowed} cuốn) theo hạng thành viên ${tier}. Vui lòng trả bớt sách trước khi mượn tiếp!`,
            status: 400
        };
    }

    return { allowed: true };
};

// =============================================
// 1. Mượn sách (Borrow Book)
// =============================================
export const borrowBook = async (req: AuthRequest, res: Response) => {
    try {
        const { bookId, bookItemId } = req.body;
        const userId = req.user?.userId;

        if (!userId) return res.status(401).json({ error: 'Unauthorized' });

        // --- KIỂM DUYỆT RỦI RO (Blacklist, Quá hạn, Hạn mức gói thành viên) ---
        const riskCheck = await validateBorrowRisk(userId);
        if (!riskCheck.allowed) {
            return res.status(riskCheck.status || 400).json({ error: riskCheck.error });
        }

        // 1. Tìm bản sao vật lý (BookItem) đang AVAILABLE
        let item = null;
        if (bookItemId) {
            item = await prisma.bookItem.findFirst({
                where: {
                    id: Number(bookItemId),
                    status: BOOK_ITEM_STATUS.AVAILABLE
                },
                include: { book: true }
            });
            if (!item) {
                return res.status(400).json({ error: 'Cuốn sách này hiện không khả dụng' });
            }
        } else if (bookId) {
            item = await prisma.bookItem.findFirst({
                where: {
                    bookId: Number(bookId),
                    status: BOOK_ITEM_STATUS.AVAILABLE
                },
                include: { book: true }
            });
            if (!item) {
                return res.status(400).json({ error: 'Sách đã hết bản có sẵn' });
            }
        } else {
            return res.status(400).json({ error: 'Thiếu bookId hoặc bookItemId' });
        }

        // 2. Chạy $transaction: Cập nhật BookItem -> BORROWED & Tạo Loan -> ACTIVE
        const dueDate = calculateDueDate(new Date());

        const [updatedBookItem, createdLoan] = await prisma.$transaction([
            prisma.bookItem.update({
                where: { id: item.id },
                data: { status: BOOK_ITEM_STATUS.BORROWED }
            }),
            prisma.loan.create({
                data: {
                    userId,
                    bookItemId: item.id,
                    borrowDate: new Date(),
                    dueDate,
                    status: LOAN_STATUS.ACTIVE,
                    fineAmount: 0,
                    compensationAmount: 0,
                    isFinePaid: false,
                    renewalStatus: RENEWAL_STATUS.NONE
                },
                include: {
                    bookItem: {
                        include: {
                            book: {
                                include: { author: true, category: true, items: true }
                            }
                        }
                    },
                    user: true
                }
            })
        ]);

        // 3. Đếm số lượng sách khả dụng (AVAILABLE) còn lại
        const availableCopies = await prisma.bookItem.count({
            where: {
                bookId: item.bookId,
                status: BOOK_ITEM_STATUS.AVAILABLE
            }
        });

        // 4. Trigger Event-Driven Notification: Mượn sách thành công
        const bookTitle = createdLoan.bookItem?.book?.title || 'Sách';
        const formattedDueDate = new Date(dueDate).toLocaleDateString('vi-VN');
        await createNotification({
            userId,
            title: 'Mượn sách thành công',
            message: `Bạn đã mượn thành công cuốn sách "${bookTitle}". Hạn hoàn trả sách: ${formattedDueDate}.`
        });

        res.json({
            ...formatLoanResponse(createdLoan, availableCopies),
            available: availableCopies,
            availableCopies
        });
    } catch (error) {
        console.error('Error borrowing book:', error);
        res.status(500).json({ error: 'Không thể mượn sách. Giao dịch đã được hủy an toàn.' });
    }
};

// =============================================
// 2. Mượn sách qua Quét mã vạch (Admin Barcode Borrow)
// =============================================
export const borrowByBarcode = async (req: AuthRequest, res: Response) => {
    try {
        if (req.user?.role !== 'ADMIN') {
            return res.status(403).json({ error: 'Chỉ thủ thư mới có quyền tạo phiếu mượn' });
        }

        const { barcode, userId } = req.body;
        if (!barcode || !userId) {
            return res.status(400).json({ error: 'Thiếu mã vạch hoặc mã độc giả' });
        }

        const bookItem = await prisma.bookItem.findUnique({
            where: { barcode: String(barcode).trim() },
            include: { book: true }
        });

        if (!bookItem) {
            return res.status(404).json({ error: `Không tìm thấy cuốn sách với mã vạch "${barcode}"` });
        }

        if (bookItem.status !== BOOK_ITEM_STATUS.AVAILABLE) {
            return res.status(400).json({
                error: `Cuốn sách này đang ở trạng thái "${bookItem.status}", không thể cho mượn`
            });
        }

        const borrower = await prisma.user.findUnique({ where: { id: Number(userId) } });
        if (!borrower) {
            return res.status(404).json({ error: 'Không tìm thấy độc giả' });
        }

        const riskCheck = await validateBorrowRisk(Number(userId));
        if (!riskCheck.allowed) {
            return res.status(riskCheck.status || 400).json({ error: riskCheck.error });
        }

        const dueDate = calculateDueDate(new Date(), borrower.membershipTier);

        // $transaction: BookItem -> BORROWED & Loan -> ACTIVE
        const [updatedItem, createdLoan] = await prisma.$transaction([
            prisma.bookItem.update({
                where: { id: bookItem.id },
                data: { status: BOOK_ITEM_STATUS.BORROWED }
            }),
            prisma.loan.create({
                data: {
                    userId: Number(userId),
                    bookItemId: bookItem.id,
                    borrowDate: new Date(),
                    dueDate,
                    status: LOAN_STATUS.ACTIVE,
                    fineAmount: 0,
                    compensationAmount: 0,
                    isFinePaid: false,
                    renewalStatus: RENEWAL_STATUS.NONE
                },
                include: {
                    bookItem: {
                        include: {
                            book: { include: { author: true, category: true, items: true } }
                        }
                    },
                    user: true
                }
            })
        ]);

        const availableCopies = await prisma.bookItem.count({
            where: {
                bookId: bookItem.bookId,
                status: BOOK_ITEM_STATUS.AVAILABLE
            }
        });

        // Trigger Event-Driven Notification: Phiếu mượn mới
        const formattedBarcodeDue = new Date(dueDate).toLocaleDateString('vi-VN');
        await createNotification({
            userId: Number(userId),
            title: 'Phiếu mượn sách mới',
            message: `Thư viện đã tạo phiếu mượn cuốn sách "${bookItem.book.title}" cho bạn. Hạn hoàn trả: ${formattedBarcodeDue}.`
        });

        res.json({
            message: `Cho mượn thành công: "${bookItem.book.title}" → ${borrower.name}`,
            loan: formatLoanResponse(createdLoan, availableCopies),
            available: availableCopies,
            availableCopies
        });
    } catch (error) {
        console.error('Error borrowing by barcode:', error);
        res.status(500).json({ error: 'Không thể tạo phiếu mượn' });
    }
};

// =============================================
// 3. Trả sách & Đóng phiếu mượn (Return Book)
// =============================================
export const returnBook = async (req: AuthRequest, res: Response) => {
    try {
        if (req.user?.role !== 'ADMIN') return res.status(403).json({ error: 'Chỉ thủ thư mới có quyền thu hồi sách' });

        const { loanId } = req.body;
        if (!loanId) return res.status(400).json({ error: 'Thiếu mã phiếu mượn (loanId)' });

        const loan = await prisma.loan.findUnique({
            where: { id: Number(loanId) },
            include: {
                bookItem: {
                    include: {
                        book: true
                    }
                },
                user: true
            }
        });

        if (!loan) {
            return res.status(404).json({ error: 'Không tìm thấy phiếu mượn' });
        }

        if (loan.status === LOAN_STATUS.COMPLETED) {
            return res.status(400).json({ error: 'Phiếu mượn này đã hoàn tất trước đó' });
        }

        const now = new Date();
        const lateFine = calculateFine(new Date(loan.dueDate), now);

        // Tính tiền phạt trễ hạn nếu có
        let calculatedFine = loan.fineAmount || 0;
        if (lateFine > 0 && !loan.isFinePaid) {
            calculatedFine = Math.max(calculatedFine, lateFine);
        }

        // Quyết định trạng thái theo State Machine:
        // Nếu còn nợ phạt chưa thanh toán -> Giữ OVERDUE; nếu không có nợ phạt (hoặc đã trả) -> COMPLETED
        const hasUnpaidFine = !loan.isFinePaid && (calculatedFine > 0 || (loan.compensationAmount && loan.compensationAmount > 0));
        const targetLoanStatus = hasUnpaidFine ? LOAN_STATUS.OVERDUE : LOAN_STATUS.COMPLETED;

        // $transaction: Trả sách vật lý BookItem -> AVAILABLE, cập nhật Loan
        const [updatedLoan] = await prisma.$transaction([
            prisma.loan.update({
                where: { id: Number(loanId) },
                data: {
                    returnDate: now,
                    status: targetLoanStatus,
                    fineAmount: calculatedFine
                },
                include: {
                    bookItem: {
                        include: {
                            book: {
                                include: { author: true, category: true, items: true }
                            }
                        }
                    },
                    user: true
                }
            }),
            prisma.bookItem.update({
                where: { id: loan.bookItemId },
                data: { status: BOOK_ITEM_STATUS.AVAILABLE }
            })
        ]);

        const availableCopies = await prisma.bookItem.count({
            where: {
                bookId: loan.bookItem.bookId,
                status: BOOK_ITEM_STATUS.AVAILABLE
            }
        });

        const bookTitle = updatedLoan.bookItem?.book?.title || 'Sách';

        // Kiểm tra độc giả đang đặt trước (WAITING) để chuyển sang NOTIFIED
        const pendingReservation = await prisma.reservation.findFirst({
            where: {
                bookId: loan.bookItem.bookId,
                status: 'WAITING'
            },
            orderBy: { createdAt: 'asc' },
            include: { user: true }
        });

        if (pendingReservation) {
            await prisma.reservation.update({
                where: { id: pendingReservation.id },
                data: { status: 'NOTIFIED' }
            });

            await createNotification({
                userId: pendingReservation.userId,
                title: 'Sách bạn đặt trước đã có sẵn!',
                message: `Cuốn sách "${bookTitle}" bạn đặt trước hiện đã được trả về thư viện. Vui lòng đến quầy làm thủ tục mượn!`
            });
        }

        // Trigger Event-Driven Notification cho người trả sách
        if (targetLoanStatus === LOAN_STATUS.COMPLETED) {
            await createNotification({
                userId: loan.userId,
                title: 'Trả sách thành công',
                message: `Bạn đã hoàn tất trả cuốn sách "${bookTitle}". Phiếu mượn đã được đóng thành công!`
            });
        } else {
            await createNotification({
                userId: loan.userId,
                title: 'Đã nhận lại sách (Chờ nộp phạt)',
                message: `Thư viện đã nhận lại cuốn sách "${bookTitle}". Do quá hạn, bạn có khoản tiền phạt ${calculatedFine.toLocaleString('vi-VN')} VNĐ cần thanh toán để hoàn tất phiếu mượn!`
            });
        }

        res.json({
            ...formatLoanResponse(updatedLoan, availableCopies),
            available: availableCopies,
            availableCopies,
            reservationNotice: pendingReservation ? {
                userName: pendingReservation.user.name,
                userEmail: pendingReservation.user.email
            } : null
        });
    } catch (error) {
        console.error('Error returning book:', error);
        res.status(500).json({ error: 'Không thể thực hiện trả sách' });
    }
};

