/**
 * POST & GET /api/payments/callback
 * Xử lý kết quả trả về sau khi người dùng xác nhận thanh toán giả lập
 */
export const paymentCallback = async (req: AuthRequest, res: Response) => {
  try {
    const payload = req.method === 'POST' ? req.body : req.query;
    const loanId = Number(payload.loanId);
    const txnRef = String(payload.txnRef || `TXN-${Date.now()}`);
    const method = String(payload.method || 'MOMO');
    const status = String(payload.status || 'SUCCESS');

    if (!loanId) {
      return res.status(400).json({ error: 'Thiếu mã phiếu mượn (loanId)' });
    }

    const loan = await prisma.loan.findUnique({
      where: { id: loanId },
      include: {
        bookItem: {
          include: { book: true }
        },
        user: true
      }
    });

    if (!loan) {
      return res.status(404).json({ error: 'Không tìm thấy phiếu mượn' });
    }

    if (status !== 'SUCCESS') {
      return res.status(400).json({ error: 'Giao dịch thanh toán không thành công hoặc đã bị hủy' });
    }

    // Cập nhật CSDL: Đánh dấu đã thanh toán phạt & chuyển status thành COMPLETED
    const updatedLoan = await prisma.loan.update({
      where: { id: loanId },
      data: {
        isFinePaid: true,
        finePaidAt: new Date(),
        paymentMethod: method,
        paymentTransactionId: txnRef,
        status: 'COMPLETED'
      },
      include: {
        bookItem: {
          include: { book: true }
        },
        user: true
      }
    });

    // Ghi nhật ký hệ thống (AuditLog)
    await prisma.auditLog.create({
      data: {
        action: 'FINE_PAYMENT',
        adminId: req.user?.userId || updatedLoan.userId,
        details: JSON.stringify({
          loanId: updatedLoan.id,
          userId: updatedLoan.userId,
          fineAmount: updatedLoan.fineAmount,
          compensationAmount: updatedLoan.compensationAmount,
          paymentMethod: method,
          paymentTransactionId: txnRef,
          paidAt: updatedLoan.finePaidAt
        })
      }
    });

    // Trigger Event-Driven Notification: Đóng phiếu mượn sau khi nộp phạt thành công
    const bookTitle = updatedLoan.bookItem?.book?.title || 'Sách mượn';
    await createNotification({
      userId: updatedLoan.userId,
      title: 'Thanh toán phí phạt thành công',
      message: `Thanh toán phí phạt cho cuốn sách "${bookTitle}" thành công (Mã GD: ${txnRef}). Phiếu mượn của bạn đã được đóng hoàn tất.`
    });

    res.json({
      success: true,
      message: 'Thanh toán phí phạt thành công, phiếu mượn của bạn đã được đóng hoàn tất!',
      loanId: updatedLoan.id,
      paymentTransactionId: txnRef,
      paidAt: updatedLoan.finePaidAt,
      status: 'COMPLETED'
    });
  } catch (error: any) {
    console.error('Error handling payment callback:', error);
    res.status(500).json({ error: error.message || 'Lỗi khi xử lý kết quả thanh toán' });
  }
};

import { Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { AuthRequest } from '../middleware/auth';
import { createNotification } from '../services/notificationService';

const prisma = new PrismaClient();

// Helper to format reservation response
const formatReservationResponse = (reservation: any) => {
    return {
        id: reservation.id,
        userId: reservation.userId,
        bookId: reservation.bookId,
        status: reservation.status, // WAITING, NOTIFIED, FULFILLED, CANCELLED
        createdAt: reservation.createdAt,
        user: reservation.user ? {
            id: reservation.user.id,
            name: reservation.user.name,
            email: reservation.user.email,
            membershipTier: reservation.user.membershipTier
        } : null,
        book: reservation.book ? {
            id: reservation.book.id,
            title: reservation.book.title,
            isbn: reservation.book.isbn,
            author: reservation.book.author?.name || '',
            category: reservation.book.category?.name || '',
            coverImage: reservation.book.coverImage,
            available: reservation.book.items
                ? reservation.book.items.filter((i: any) => i.status === 'AVAILABLE').length
                : 0,
            totalCopies: reservation.book.items ? reservation.book.items.length : 0
        } : null
    };
};

/**
 * Độc giả tạo bản ghi đặt trước (Reservation) khi đầu sách không còn bản sao nào trống
 */
export const createReservation = async (req: AuthRequest, res: Response) => {
    try {
        const userId = req.user?.userId;
        if (!userId) {
            return res.status(401).json({ error: 'Vui lòng đăng nhập để đặt trước sách' });
        }

        const { bookId } = req.body;
        if (!bookId) {
            return res.status(400).json({ error: 'Thiếu thông tin mã sách (bookId)' });
        }

        // 1. Kiểm tra sách có tồn tại không
        const book = await prisma.book.findUnique({
            where: { id: Number(bookId) },
            include: {
                items: true,
                author: true,
                category: true
            }
        });

        if (!book) {
            return res.status(404).json({ error: 'Không tìm thấy đầu sách này' });
        }

        // 2. Kiểm tra số lượng bản sao khả dụng (AVAILABLE)
        const availableItemsCount = await prisma.bookItem.count({
            where: {
                bookId: Number(bookId),
                status: 'AVAILABLE'
            }
        });

        if (availableItemsCount > 0) {
            return res.status(400).json({
                error: 'Đầu sách này hiện vẫn còn bản sao có sẵn trong kho. Bạn có thể mượn trực tiếp mà không cần đặt trước.'
            });
        }

        // 3. Kiểm tra xem độc giả đã đặt trước sách này và đang đợi chưa
        const existingReservation = await prisma.reservation.findFirst({
            where: {
                userId,
                bookId: Number(bookId),
                status: {
                    in: ['WAITING', 'NOTIFIED']
                }
            }
        });

        if (existingReservation) {
            return res.status(400).json({
                error: 'Bạn đã đăng ký đặt trước đầu sách này rồi (Trạng thái: ' +
                    (existingReservation.status === 'NOTIFIED' ? 'Đã có sách, đang chờ bạn đến nhận' : 'Đang chờ sách') +
                    ').'
            });
        }

        // 4. Kiểm tra xem độc giả hiện có đang giữ mượn cuốn sách này không
        const activeLoan = await prisma.loan.findFirst({
            where: {
                userId,
                returnDate: null,
                bookItem: {
                    bookId: Number(bookId)
                }
            }
        });

        if (activeLoan) {
            return res.status(400).json({
                error: 'Bạn đang mượn một bản sao của cuốn sách này rồi.'
            });
        }

        // 5. Tạo bản ghi đặt trước
        const newReservation = await prisma.reservation.create({
            data: {
                userId,
                bookId: Number(bookId),
                status: 'WAITING'
            },
            include: {
                user: true,
                book: {
                    include: {
                        author: true,
                        category: true,
                        items: true
                    }
                }
            }
        });

        // Đếm số thứ tự đang chờ trước mình
        const queuePosition = await prisma.reservation.count({
            where: {
                bookId: Number(bookId),
                status: 'WAITING'
            }
        });

        // Tạo thông báo cho người dùng
        await createNotification({
            userId,
            title: 'Đặt trước sách thành công',
            message: `Bạn đã đăng ký đặt trước cuốn sách "${book.title}". Hệ thống sẽ gửi thông báo ngay khi có sách hoàn trả về thư viện.`
        });

        res.status(201).json({
            message: `Đặt trước thành công! Bạn đang ở vị trí thứ ${queuePosition} trong danh sách chờ nhận sách "${book.title}".`,
            reservation: formatReservationResponse(newReservation),
            queuePosition
        });
    } catch (error) {
        console.error('Error creating reservation:', error);
        res.status(500).json({ error: 'Không thể tạo yêu cầu đặt trước sách' });
    }
};

/**
