/**
 * Cập nhật trạng thái đặt trước (Thủ thư thông báo, hoàn tất nhận sách, hoặc hủy)
 */
export const updateReservationStatus = async (req: AuthRequest, res: Response) => {
    try {
        if (req.user?.role !== 'ADMIN') {
            return res.status(403).json({ error: 'Chỉ thủ thư mới có quyền cập nhật trạng thái đặt trước' });
        }

        const { id } = req.params;
        const { status } = req.body;

        const validStatuses = ['WAITING', 'NOTIFIED', 'FULFILLED', 'CANCELLED'];
        if (!status || !validStatuses.includes(status)) {
            return res.status(400).json({
                error: `Trạng thái không hợp lệ. Phải là một trong các giá trị: ${validStatuses.join(', ')}`
            });
        }

        const existing = await prisma.reservation.findUnique({
            where: { id: Number(id) }
        });

        if (!existing) {
            return res.status(404).json({ error: 'Không tìm thấy bản ghi đặt trước này' });
        }

        const updated = await prisma.reservation.update({
            where: { id: Number(id) },
            data: { status },
            include: {
                user: true,
                book: {
                    include: {
                        author: true,
                        category: true,
                        items: true
                    }
                }
            }
        });

        if (status === 'NOTIFIED') {
            await createNotification({
                userId: updated.userId,
                title: 'Sách đặt trước đã có sẵn!',
                message: `Đầu sách "${updated.book.title}" bạn đặt trước hiện đã có sẵn tại thư viện. Vui lòng đến nhận sách trong vòng 48h!`
            });
        }

        res.json({
            message: 'Cập nhật trạng thái đặt trước thành công',
            reservation: formatReservationResponse(updated)
        });
    } catch (error) {
        console.error('Error updating reservation status:', error);
        res.status(500).json({ error: 'Không thể cập nhật trạng thái đặt trước' });
    }
};

/**
 * Hủy đặt trước sách (Độc giả tự hủy hoặc Thủ thư hủy)
 */
export const cancelReservation = async (req: AuthRequest, res: Response) => {
    try {
        const userId = req.user?.userId;
        const role = req.user?.role;
        const { id } = req.params;

        if (!userId) {
            return res.status(401).json({ error: 'Unauthorized' });
        }

        const reservation = await prisma.reservation.findUnique({
            where: { id: Number(id) }
        });

        if (!reservation) {
            return res.status(404).json({ error: 'Không tìm thấy bản ghi đặt trước' });
        }

        // Độc giả chỉ được hủy của chính mình, thủ thư được hủy tất cả
        if (role !== 'ADMIN' && reservation.userId !== userId) {
            return res.status(403).json({ error: 'Bạn không có quyền hủy bản ghi này' });
        }

        const updated = await prisma.reservation.update({
            where: { id: Number(id) },
            data: { status: 'CANCELLED' }
        });

        res.json({
            message: 'Đã hủy đặt trước sách thành công',
            reservation: updated
        });
    } catch (error) {
        console.error('Error cancelling reservation:', error);
        res.status(500).json({ error: 'Không thể hủy yêu cầu đặt trước' });
    }
};

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export interface AuthRequest extends Request {
    user?: {
        userId: number;
        email: string;
        role: string;
    };
}

export const authenticateToken = (req: AuthRequest, res: Response, next: NextFunction) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) return res.sendStatus(401);

    jwt.verify(token, process.env.JWT_SECRET as string, (err: any, user: any) => {
        if (err) return res.sendStatus(403);
        req.user = user;
        next();
    });
};

export const authorizeAdmin = (req: AuthRequest, res: Response, next: NextFunction) => {
    if (req.user?.role !== 'ADMIN') {
        return res.status(403).json({ message: 'Forbidden' });
    }
    next();
};

export const optionalAuthenticateToken = (req: AuthRequest, _res: Response, next: NextFunction) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) return next();

    jwt.verify(token, process.env.JWT_SECRET as string, (_err: any, user: any) => {
        if (user) {
            req.user = user;
        }
        next();
    });
};

import nodemailer, { Transporter } from 'nodemailer';

let cachedTransporter: Transporter | null = null;

/**
 * Khởi tạo hoặc tái sử dụng Transporter
 * Hỗ trợ tài khoản Gmail / SMTP thật nếu có cấu hình trong .env,
 * hoặc tự động tạo Ethereal Email giả lập để test an toàn.
 */
export const getTransporter = async (): Promise<Transporter> => {
  if (cachedTransporter) return cachedTransporter;

  if (process.env.SMTP_USER && process.env.SMTP_PASS) {
    const host = process.env.SMTP_HOST || 'smtp.gmail.com';
    const port = Number(process.env.SMTP_PORT) || 587;
    const isSecure = process.env.SMTP_SECURE === 'true' || port === 465;

    console.log(`[MailService] Đang sử dụng SMTP thật: ${host}:${port} (${process.env.SMTP_USER})`);

    cachedTransporter = nodemailer.createTransport({
      host,
      port,
      secure: isSecure,
      auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
      },
      tls: {
        rejectUnauthorized: false // Cho phép kết nối an toàn linh hoạt
      }
    });
  } else {
    console.log('[MailService] Không tìm thấy SMTP_USER/SMTP_PASS, sử dụng tài khoản Ethereal giả lập...');
    const testAccount = await nodemailer.createTestAccount();
    console.log(`[MailService] Tài khoản Ethereal: ${testAccount.user}`);

    cachedTransporter = nodemailer.createTransport({
      host: 'smtp.ethereal.email',
      port: 587,
      secure: false,
      auth: {
        user: testAccount.user,
        pass: testAccount.pass,
      },
    });
  }

  return cachedTransporter;
};


