import { useState, useRef } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { client } from '../api/client';
import { Book } from './BooksManagement';
import { toast } from 'sonner';
import {
  Sparkles,
  TrendingUp,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  BookmarkPlus,
  FileText,
  Flame,
  Award
} from 'lucide-react';

interface BookRecommendationsProps {
  onSelectBook: (book: Book) => void;
  onBorrow?: (bookId: number) => void;
  onReserve?: (bookId: number) => void;
  userRole?: 'ADMIN' | 'USER' | null;
}

interface RecommendationsResponse {
  success: boolean;
  type: 'PERSONALIZED' | 'TRENDING';
  reason: string;
  books: Book[];
}

export function BookRecommendations({
  onSelectBook,
  onBorrow,
  onReserve,
  userRole
}: BookRecommendationsProps) {
  const queryClient = useQueryClient();
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const internalBorrowMutation = useMutation({
    mutationFn: async (bookId: number) => {
      const { data } = await client.post('/loans/borrow', { bookId });
      return data;
    },
    onSuccess: (data: any, bookId: number) => {
      toast.success('Mượn sách thành công!');
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['my-loans'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      queryClient.invalidateQueries({ queryKey: ['notifications'] });

      queryClient.setQueryData<RecommendationsResponse>(['book-recommendations'], (oldData) => {
        if (!oldData || !oldData.books) return oldData;
        return {
          ...oldData,
          books: oldData.books.map((b) => {
            if (b.id === bookId) {
              const newAvailable = typeof data?.availableCopies === 'number'
                ? data.availableCopies
                : (typeof data?.available === 'number' ? data.available : Math.max(0, (b.available ?? 1) - 1));
              return {
                ...b,
                available: newAvailable,
                status: newAvailable > 0 ? 'Available' : 'Borrowed'
              };
            }
            return b;
          })
        };
      });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi xảy ra khi mượn sách');
    }
  });

  const handleBorrow = (bookId: number) => {
    if (onBorrow) {
      onBorrow(bookId);
    } else {
      internalBorrowMutation.mutate(bookId);
    }
  };

  const { data, isLoading } = useQuery<RecommendationsResponse>({
    queryKey: ['book-recommendations'],
    queryFn: async () => {
      const res = await client.get('/books/recommendations');
      return res.data;
    },
    staleTime: 5 * 60 * 1000 // 5 minutes cache
  });

  const books = data?.books || [];
  const recommendationType = data?.type || 'TRENDING';
  const reason = data?.reason || 'Gợi ý những cuốn sách được bạn đọc yêu thích nhất';

  const updateScrollButtons = () => {
    if (!scrollContainerRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
    setCanScrollLeft(scrollLeft > 10);
    setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 10);
  };

  const handleScroll = (direction: 'left' | 'right') => {
    if (!scrollContainerRef.current) return;
    const scrollAmount = 300;
    scrollContainerRef.current.scrollBy({
      left: direction === 'left' ? -scrollAmount : scrollAmount,
      behavior: 'smooth'
    });
    setTimeout(updateScrollButtons, 350);
  };

  if (isLoading) {
    return (
      <div className="bg-gradient-to-r from-blue-50/70 via-indigo-50/50 to-purple-50/70 dark:from-gray-900 dark:via-blue-950/20 dark:to-purple-950/20 border border-blue-100 dark:border-blue-900/30 rounded-2xl p-5 mb-6 shadow-sm">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-6 h-6 rounded-full bg-blue-200 dark:bg-blue-800 animate-pulse" />
          <div className="h-6 w-48 bg-blue-200/70 dark:bg-blue-800/50 rounded animate-pulse" />
        </div>
        <div className="flex gap-4 overflow-hidden">
          {[1, 2, 3, 4].map((i) => (
            <div
              key={i}
              className="w-60 h-72 flex-shrink-0 bg-white dark:bg-gray-800 rounded-xl animate-pulse p-3 space-y-3"
            >
              <div className="w-full h-36 bg-gray-200 dark:bg-gray-700 rounded-lg" />
              <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4" />
              <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-1/2" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (books.length === 0) {
    return null;
  }

  return (
    <div className="bg-gradient-to-r from-blue-50/80 via-indigo-50/60 to-purple-50/80 dark:from-gray-900/90 dark:via-indigo-950/20 dark:to-purple-950/20 border border-indigo-100 dark:border-indigo-900/40 rounded-2xl p-5 mb-6 shadow-sm relative overflow-hidden transition-all">
      {/* Decorative background glow */}
      <div className="absolute top-0 right-0 -mt-8 -mr-8 w-48 h-48 bg-gradient-to-br from-indigo-400/10 to-purple-500/10 rounded-full blur-2xl pointer-events-none" />

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4 relative z-10">
        <div>
          <div className="flex items-center gap-2">
            <div className="p-1.5 bg-gradient-to-tr from-amber-500 to-indigo-600 text-white rounded-lg shadow-sm">
              <Sparkles size={18} />
            </div>
            <h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2">
              Gợi ý dành riêng cho bạn
              {recommendationType === 'PERSONALIZED' ? (
                <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-indigo-100 text-indigo-700 dark:bg-indigo-900/50 dark:text-indigo-300 border border-indigo-200 dark:border-indigo-800">
                  Phù hợp với bạn
                </span>
              ) : (
                <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-100 text-rose-700 dark:bg-rose-900/50 dark:text-rose-300 border border-rose-200 dark:border-rose-800">
                  Thịnh hành
                </span>
              )}
            </h3>
          </div>
          <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 flex items-center gap-1.5">
            {recommendationType === 'PERSONALIZED' ? (
              <Award size={14} className="text-indigo-500 shrink-0" />
            ) : (
              <Flame size={14} className="text-rose-500 shrink-0" />
            )}
            <span>{reason}</span>
          </p>
        </div>

        {/* Carousel arrows */}
        <div className="flex items-center gap-2 self-end sm:self-center">
          <button
            onClick={() => handleScroll('left')}
            disabled={!canScrollLeft}
            className={`p-2 rounded-lg border transition-all ${
              canScrollLeft
                ? 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 border-gray-200 dark:border-gray-700 shadow-sm hover:bg-gray-50 active:scale-95'
                : 'bg-gray-100 dark:bg-gray-800/50 text-gray-300 dark:text-gray-600 border-transparent cursor-not-allowed'
            }`}
            title="Cuộn sang trái"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={() => handleScroll('right')}
            disabled={!canScrollRight}
            className={`p-2 rounded-lg border transition-all ${
              canScrollRight
                ? 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 border-gray-200 dark:border-gray-700 shadow-sm hover:bg-gray-50 active:scale-95'
                : 'bg-gray-100 dark:bg-gray-800/50 text-gray-300 dark:text-gray-600 border-transparent cursor-not-allowed'
            }`}
            title="Cuộn sang phải"
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>

      {/* Books Carousel Row */}
      <div
        ref={scrollContainerRef}
        onScroll={updateScrollButtons}
        className="flex gap-4 overflow-x-auto scroll-smooth pb-2 pt-1 -mx-1 px-1 no-scrollbar focus:outline-none"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
      >
        {books.map((book) => {
          const isPersonalized = book.recommendationBadge === 'Phù hợp với bạn';

          return (
            <div
              key={book.id}
              onClick={() => onSelectBook(book)}
              className="w-60 flex-shrink-0 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700/80 shadow-sm hover:shadow-md hover:-translate-y-1 transition-all duration-200 flex flex-col cursor-pointer group overflow-hidden"
            >
              {/* Cover Image Container */}
              <div className="h-40 relative overflow-hidden bg-gray-100 dark:bg-gray-900">
                <img
                  src={book.coverImage || 'https://via.placeholder.com/300x400?text=No+Cover'}
                  alt={book.title}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                />

                {/* Recommendation Badge */}
                <div className="absolute top-2 left-2 z-10">
                  <span
                    className={`inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-full shadow-sm text-white ${
                      isPersonalized
                        ? 'bg-gradient-to-r from-purple-600 to-indigo-600'
                        : 'bg-gradient-to-r from-amber-500 to-rose-600'
                    }`}
                  >
                    {isPersonalized ? <Sparkles size={11} /> : <TrendingUp size={11} />}
                    {book.recommendationBadge || (isPersonalized ? 'Phù hợp với bạn' : 'Thịnh hành')}
                  </span>
                </div>

                {/* Ebook tag if available */}
                {book.ebookUrl && (
                  <div className="absolute top-2 right-2 px-1.5 py-0.5 bg-emerald-600/90 backdrop-blur-md rounded text-[10px] text-white font-medium flex items-center gap-0.5 shadow">
                    <FileText size={10} /> PDF
                  </div>
                )}

                {/* Category tag at bottom of image */}
                <div className="absolute bottom-2 right-2 px-2 py-0.5 bg-black/60 backdrop-blur-md rounded text-[11px] text-white">
                  {book.category}
                </div>
              </div>

              {/* Card Body */}
              <div className="p-3.5 flex-1 flex flex-col justify-between">
                <div>
                  <h4
                    className="font-bold text-sm text-gray-800 dark:text-gray-100 line-clamp-2 mb-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors"
                    title={book.title}
                  >
                    {book.title}
                  </h4>
                  <p className="text-xs text-gray-500 dark:text-gray-400 truncate mb-2">
                    {book.author}
                  </p>

                  {/* Recommendation context pill */}
                  {book.recommendationReason && (
                    <div className="mb-3 px-2 py-1 bg-indigo-50 dark:bg-indigo-950/40 rounded text-[11px] text-indigo-700 dark:text-indigo-300 truncate">
                      💡 {book.recommendationReason}
                    </div>
                  )}
                </div>

                {/* Footer Status & Action */}
                <div className="pt-2 border-t border-gray-100 dark:border-gray-700/60 flex items-center justify-between gap-2">
                  <div>
                    <span
                      className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${
                        book.available > 0
                          ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
                          : 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'
                      }`}
                    >
                      {book.available > 0 ? `Còn ${book.available} bản` : 'Hết sách'}
                    </span>
                  </div>

                  {userRole !== 'ADMIN' && (
                    book.available > 0 ? (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleBorrow(book.id);
                        }}
                        disabled={internalBorrowMutation.isPending}
                        className="px-2.5 py-1 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white text-xs font-medium rounded-lg transition-colors shadow-sm flex items-center gap-1 active:scale-95"
                      >
                        <BookOpen size={12} />
                        Mượn
                      </button>
                    ) : (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          if (onReserve) onReserve(book.id);
                        }}
                        className="px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white text-xs font-medium rounded-lg transition-colors shadow-sm flex items-center gap-1 active:scale-95"
                      >
                        <BookmarkPlus size={12} />
                        Đặt trước
                      </button>
                    )
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { Search, Plus, Edit, Trash2, BookOpen, Filter, X, FileSpreadsheet, Upload, CheckCircle, AlertCircle, Loader2, FileText } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { client } from '../api/client';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { BookDetailModal } from './BookDetailModal';
import { BookRecommendations } from './BookRecommendations';
import { ImportExcelModal } from './ImportExcelModal';
import { toast } from 'sonner';

export interface BookItem {
  id: number;
  barcode: string;
  location?: string | null;
  status: string;
}

export interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  category: string;
  status: string;
  copies: number;
  available: number;
  publishedYear?: string;
  publisher?: string;
  coverImage?: string;
  description?: string;
  pageCount?: number;
  language?: string;
  ebookUrl?: string | null;
  recommendationBadge?: string;
  recommendationReason?: string;
  items?: BookItem[];
}

interface BooksManagementProps {
  userRole?: 'ADMIN' | 'USER' | null;
  books?: any;
  setBooks?: any;
  onBorrow?: any;
}

export function BooksManagement({ userRole: propUserRole }: BooksManagementProps = {}) {
  const { t } = useLanguage();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [showModal, setShowModal] = useState(false);
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const ebookFileInputRef = useRef<HTMLInputElement>(null);
  const [uploadingEbook, setUploadingEbook] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    author: '',
    isbn: '',
    category: '',
    copies: 1,
    available: 1,
    publishedYear: '',
    publisher: '',
    pageCount: 0,
    language: 'Tiếng Việt',
    description: '',
    coverImage: '',
    ebookUrl: ''
  });

  const { user } = useAuth();
  const userRole = propUserRole || user?.role;
  const queryClient = useQueryClient();

  // Fetch Books
  const { data: books = [], isLoading } = useQuery({
    queryKey: ['books'],
    queryFn: async () => {
      const { data } = await client.get('/books');
      return data as Book[];
    }
  });

  // Keep selectedBook synced with latest books data from query refetch
  useEffect(() => {
    if (selectedBook) {
      const updated = books.find(b => b.id === selectedBook.id);
      if (updated) {
        setSelectedBook(updated);
      }
    }
  }, [books]);

  // Create Book Mutation (Smart Inventory Merge)
  const createMutation = useMutation({
    mutationFn: async (bookData: any) => {
      const { data } = await client.post('/books', bookData);
      return data;
    },
    onSuccess: (data: any) => {
      toast.success(data?.message || 'Thêm sách thành công!');
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      queryClient.invalidateQueries({ queryKey: ['top-books'] });
      setShowModal(false);
      resetForm();
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi thêm sách');
    }
  });

  // Update Book Mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: any }) => {
      await client.put(`/books/${id}`, data);
    },
    onSuccess: () => {
      toast.success('Cập nhật thông tin sách thành công!');
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      setShowModal(false);
      setEditingBook(null);
      resetForm();
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi cập nhật sách');
    }
  });

  // Delete Book Mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      await client.delete(`/books/${id}`);
    },
    onSuccess: () => {
      toast.success('Xóa sách thành công!');
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi xóa sách');
    }
  });

  // Borrow Mutation
  const borrowMutation = useMutation({
    mutationFn: async (bookId: number) => {
      const { data } = await client.post('/loans/borrow', { bookId });
      return data;
    },
    onSuccess: (data: any, bookId: number) => {
      toast.success('Mượn sách thành công!');

      // Bắt buộc gọi invalidateQueries để React tự động fetch lại danh sách sách và cập nhật con số chính xác
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['my-loans'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      queryClient.invalidateQueries({ queryKey: ['top-books'] });
      queryClient.invalidateQueries({ queryKey: ['recent-activity'] });
      queryClient.invalidateQueries({ queryKey: ['borrow-trends'] });
      queryClient.invalidateQueries({ queryKey: ['notifications'] });

      // Cập nhật ngay trong cache của ['books'] để giao diện phản hồi lập tức không độ trễ
      queryClient.setQueryData<Book[]>(['books'], (oldBooks) => {
        if (!oldBooks) return oldBooks;
        return oldBooks.map((b) => {
          if (b.id === bookId) {
            const newAvailable = typeof data?.availableCopies === 'number'
              ? data.availableCopies
              : (typeof data?.available === 'number' ? data.available : Math.max(0, (b.available ?? 1) - 1));
            return {
              ...b,
              available: newAvailable,
              status: newAvailable > 0 ? 'Available' : 'Borrowed'
            };
          }
          return b;
        });
      });

      // Cập nhật ngay trong cache của ['book-recommendations']
      queryClient.setQueryData<any>(['book-recommendations'], (oldData) => {
        if (!oldData || !oldData.books) return oldData;
        return {
          ...oldData,
          books: oldData.books.map((b: Book) => {
            if (b.id === bookId) {
              const newAvailable = typeof data?.availableCopies === 'number'
                ? data.availableCopies
                : (typeof data?.available === 'number' ? data.available : Math.max(0, (b.available ?? 1) - 1));
              return {
                ...b,
                available: newAvailable,
                status: newAvailable > 0 ? 'Available' : 'Borrowed'
              };
            }
            return b;
          })
        };
      });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi xảy ra khi mượn sách');
    }
  });

  // Reserve Mutation
  const reserveMutation = useMutation({
    mutationFn: async (bookId: number) => {
      const { data } = await client.post('/reservations', { bookId });
      return data;
    },
    onSuccess: (data: any) => {
      toast.success(data.message || 'Đặt trước sách thành công!');
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
      queryClient.invalidateQueries({ queryKey: ['my-reservations'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi đặt trước sách');
    }
  });

  const resetForm = () => {
    setFormData({
      title: '',
      author: '',
      isbn: '',
      category: '',
      copies: 1,
      available: 1,
      publishedYear: '',
      publisher: '',
      pageCount: 0,
      language: 'Tiếng Việt',
      description: '',
      coverImage: '',
      ebookUrl: ''
    });
    if (ebookFileInputRef.current) {
      ebookFileInputRef.current.value = '';
    }
  };

  const handleAddBook = () => {
    setEditingBook(null);
    resetForm();
    setShowModal(true);
  };

  const handleEditBook = (book: Book) => {
    setEditingBook(book);
    setFormData({
      title: book.title,
      author: book.author,
      isbn: book.isbn,
      category: book.category,
      copies: book.copies,
      available: book.available,
      publishedYear: book.publishedYear || '',
      publisher: book.publisher || '',
      pageCount: book.pageCount || 0,
      language: book.language || 'Tiếng Việt',
      description: book.description || '',
      coverImage: book.coverImage || '',
      ebookUrl: book.ebookUrl || ''
    });
    setShowModal(true);
  };

  const handleEbookFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 50 * 1024 * 1024) {
      toast.error('Dung lượng file vượt quá giới hạn cho phép (tối đa 50MB)');
      return;
    }

    setUploadingEbook(true);
    const data = new FormData();
    data.append('file', file);

    try {
      const res = await client.post('/books/upload-ebook', data, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setFormData(prev => ({ ...prev, ebookUrl: res.data.ebookUrl }));
      toast.success('Tải lên file E-book thành công!');
    } catch (err: any) {
      toast.error(err.response?.data?.error || 'Có lỗi xảy ra khi tải file E-book');
    } finally {
      setUploadingEbook(false);
    }
  };

  const handleDeleteBook = (id: number, title: string) => {
    if (confirm(`Bạn có chắc chắn muốn xóa sách "${title}"?`)) {
      deleteMutation.mutate(id);
    }
  };

  const handleBookClick = (book: Book) => {
    setSelectedBook(book);
    setShowDetailModal(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.author || !formData.isbn || !formData.category) {
      toast.error('Vui lòng điền đầy đủ thông tin bắt buộc (tiêu đề, tác giả, ISBN, thể loại)');
      return;
    }

    const bookData = {
      ...formData,
      status: 'Available',
      pageCount: formData.pageCount || null,
      publishedYear: formData.publishedYear || null,
      publisher: formData.publisher || null,
      description: formData.description || null,
      coverImage: formData.coverImage || null,
      ebookUrl: formData.ebookUrl || null
    };

    if (editingBook) {
      updateMutation.mutate({ id: editingBook.id, data: bookData });
    } else {
      createMutation.mutate(bookData);
    }
  };

  const filteredBooks = books.filter(book => {
    const matchesSearch = book.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      book.author.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || book.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const categories = ['All', ...Array.from(new Set(books.map(b => b.category)))];

  if (isLoading) {
    return <div className="p-8 text-center text-gray-500">{t('books.loading')}</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
            <BookOpen className="text-blue-600" />
            {t('books.title')}
          </h2>
          <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">{t('books.subtitle')}</p>
        </div>

        {userRole === 'ADMIN' && (
          <div className="flex items-center gap-3">
            <button
              onClick={() => setIsImportModalOpen(true)}
              className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition-colors shadow-sm font-semibold"
            >
              <FileSpreadsheet size={18} />
              {t('books.importExcel') || 'Import Excel'}
            </button>
            <button
              onClick={handleAddBook}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors shadow-sm font-semibold"
            >
              <Plus size={18} />
              {t('books.addNew')}
            </button>
          </div>
        )}
      </div>

      {/* Smart Book Recommendations Carousel */}
      <BookRecommendations
        onSelectBook={handleBookClick}
        onBorrow={(bookId) => borrowMutation.mutate(bookId)}
        onReserve={(bookId) => reserveMutation.mutate(bookId)}
        userRole={userRole}
      />

      {/* Filter Bar */}
      <div className="bg-white dark:bg-gray-900 p-4 rounded-xl shadow-sm border border-gray-200 dark:border-gray-800 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input
            type="text"
            placeholder={t('books.search')}
            className="w-full pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2">
          <Filter size={18} className="text-gray-500" />
          <select
            className="px-4 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
          >
            {categories.map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Books Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {filteredBooks.map((book) => (
          <div
            key={book.id}
            className="bg-white dark:bg-gray-900 rounded-xl shadow-sm border border-gray-200 dark:border-gray-800 overflow-hidden hover:shadow-md transition-shadow flex flex-col h-full cursor-pointer"
            onClick={() => handleBookClick(book)}
          >
            <div className="h-48 overflow-hidden relative group">
              <img
                src={book.coverImage || 'https://via.placeholder.com/300x400?text=No+Cover'}
                alt={book.title}
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
              />
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                {/* Quick Actions overlay? */}
              </div>
              <div className="absolute top-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-xs text-white">
                {book.category}
              </div>
              {book.ebookUrl && (
                <div className="absolute top-2 left-2 px-2 py-1 bg-emerald-600/90 backdrop-blur-md rounded text-xs text-white font-medium flex items-center gap-1 shadow">
                  <FileText size={12} /> E-book
                </div>
              )}
            </div>

            <div className="p-4 flex-1 flex flex-col">
              <h3 className="font-bold text-gray-800 dark:text-gray-100 line-clamp-2 min-h-[3rem] mb-1" title={book.title}>
                {book.title}
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-2 truncate">{book.author}</p>

              <div className="mt-auto pt-3 border-t border-gray-100 dark:border-gray-800 flex items-center justify-between">
                <div>
                  <span className={`text-xs font-medium px-2 py-1 rounded-full ${book.available > 0
                    ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
                    : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                    }`}>
                    {book.available > 0 ? t('books.available') : t('books.outOfStock')}
                  </span>
                  <p className="text-xs text-gray-400 mt-1">{t('books.remaining')} {book.available}/{book.copies}</p>
                </div>

                {userRole === 'ADMIN' ? (
                  <div className="flex gap-2">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleEditBook(book);
                      }}
                      className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors text-blue-600"
                      title={t('common.edit')}
                    >
                      <Edit size={18} />
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteBook(book.id, book.title);
                      }}
                      className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors text-red-600"
                      title={t('common.delete')}
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                ) : (
                  book.available > 0 ? (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        borrowMutation.mutate(book.id);
                      }}
                      disabled={borrowMutation.isPending}
                      className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
                    >
                      {t('books.borrow')}
                    </button>
                  ) : (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        reserveMutation.mutate(book.id);
                      }}
                      disabled={reserveMutation.isPending}
                      className="px-3 py-2 bg-amber-600 hover:bg-amber-700 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
                      title={t('books.reserve')}
                    >
                      {t('books.reserve')}
                    </button>
                  )
                )}
              </div>
            </div>
          </div>
        ))}

        {filteredBooks.length === 0 && (
          <div className="col-span-full text-center py-12 text-gray-500 dark:text-gray-400">
            {t('books.notFound')}
          </div>
        )}
      </div>

      {/* Add/Edit Book Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-900 rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="sticky top-0 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 p-4 flex items-center justify-between">
              <h3 className="text-xl font-bold text-gray-800 dark:text-white">
                {editingBook ? 'Chỉnh sửa sách' : 'Thêm sách mới'}
              </h3>
              <button
                onClick={() => { setShowModal(false); setEditingBook(null); resetForm(); }}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    Tiêu đề <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    Tác giả <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.author}
                    onChange={(e) => setFormData({ ...formData, author: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    ISBN <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.isbn}
                    onChange={(e) => setFormData({ ...formData, isbn: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    Thể loại <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    Số lượng <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    required
                    min="1"
                    value={formData.copies}
                    onChange={(e) => setFormData({ ...formData, copies: parseInt(e.target.value) })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">
                    Còn lại <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    required
                    min="0"
                    value={formData.available}
                    onChange={(e) => setFormData({ ...formData, available: parseInt(e.target.value) })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Năm xuất bản</label>
                  <input
                    type="text"
                    value={formData.publishedYear}
                    onChange={(e) => setFormData({ ...formData, publishedYear: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Nhà xuất bản</label>
                  <input
                    type="text"
                    value={formData.publisher}
                    onChange={(e) => setFormData({ ...formData, publisher: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Số trang</label>
                  <input
                    type="number"
                    value={formData.pageCount}
                    onChange={(e) => setFormData({ ...formData, pageCount: parseInt(e.target.value) })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Ngôn ngữ</label>
                  <input
                    type="text"
                    value={formData.language}
                    onChange={(e) => setFormData({ ...formData, language: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">URL ảnh bìa</label>
                  <input
                    type="text"
                    value={formData.coverImage}
                    onChange={(e) => setFormData({ ...formData, coverImage: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div className="col-span-2 space-y-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    File E-book (PDF - Tùy chọn)
                  </label>
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                    <input
                      type="file"
                      ref={ebookFileInputRef}
                      accept=".pdf,.epub,application/pdf,application/epub+zip"
                      onChange={handleEbookFileUpload}
                      className="hidden"
                      id="ebook-upload-input"
                    />
                    <label
                      htmlFor="ebook-upload-input"
                      className={`flex items-center justify-center gap-2 px-4 py-2 border border-dashed rounded-lg cursor-pointer transition-colors text-sm font-medium ${
                        uploadingEbook
                          ? 'bg-gray-100 dark:bg-gray-800 text-gray-400 border-gray-300 cursor-not-allowed'
                          : 'border-blue-300 dark:border-blue-700 hover:bg-blue-50 dark:hover:bg-blue-900/20 text-blue-600 dark:text-blue-400 bg-white dark:bg-gray-800'
                      }`}
                    >
                      {uploadingEbook ? (
                        <>
                          <Loader2 size={16} className="animate-spin" />
                          Đang tải lên server...
                        </>
                      ) : (
                        <>
                          <Upload size={16} />
                          {formData.ebookUrl ? 'Thay đổi file E-book' : 'Tải lên file E-book (.pdf, .epub)'}
                        </>
                      )}
                    </label>

                    {formData.ebookUrl && (
                      <div className="flex items-center gap-2 px-3 py-2 bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-800 rounded-lg text-xs text-emerald-700 dark:text-emerald-300 flex-1 min-w-0">
                        <FileText size={16} className="shrink-0 text-emerald-600 dark:text-emerald-400" />
                        <span className="truncate flex-1 font-mono" title={formData.ebookUrl}>
                          {formData.ebookUrl}
                        </span>
                        <a
                          href={formData.ebookUrl.startsWith('http') ? formData.ebookUrl : `http://localhost:5000${formData.ebookUrl}`}
                          target="_blank"
                          rel="noreferrer"
                          className="px-2 py-0.5 bg-emerald-100 dark:bg-emerald-900/50 hover:bg-emerald-200 text-emerald-800 dark:text-emerald-200 rounded font-medium shrink-0 ml-1 transition-colors"
                        >
                          Xem thử
                        </a>
                        <button
                          type="button"
                          onClick={() => {
                            setFormData(prev => ({ ...prev, ebookUrl: '' }));
                            if (ebookFileInputRef.current) ebookFileInputRef.current.value = '';
                          }}
                          className="p-1 hover:bg-red-100 dark:hover:bg-red-900/50 rounded text-red-500 shrink-0 transition-colors"
                          title="Gỡ bỏ file E-book"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    )}
                  </div>
                  <p className="text-xs text-gray-400">
                    Hỗ trợ file PDF hoặc EPUB (tối đa 50MB). Khi tải lên, đường dẫn sẽ tự động được lưu và độc giả có thể đọc trực tuyến.
                  </p>
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Mô tả</label>
                  <textarea
                    rows={3}
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="submit"
                  disabled={createMutation.isPending || updateMutation.isPending}
                  className="flex-1 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white rounded-lg transition-colors font-medium"
                >
                  {editingBook ? 'Cập nhật' : 'Thêm sách'}
                </button>
                <button
                  type="button"
                  onClick={() => { setShowModal(false); setEditingBook(null); resetForm(); }}
                  className="px-4 py-2 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-lg transition-colors"
                >
                  Hủy
                </button>

              </div>
            </form>
          </div>
        </div>
      )}

      {/* Bulk Import Excel Modal */}
      <ImportExcelModal
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
      />

      {/* Book Detail Modal */}
      <BookDetailModal
        book={selectedBook}
        isOpen={showDetailModal}
        onClose={() => setShowDetailModal(false)}
        onBorrow={(bookId) => borrowMutation.mutate(bookId)}
        onReserve={(bookId) => reserveMutation.mutate(bookId)}
        onEdit={userRole === 'ADMIN' ? handleEditBook : undefined}
        onDelete={userRole === 'ADMIN' ? handleDeleteBook : undefined}
        userRole={userRole}
      />
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import {
  Search, RotateCcw, AlertCircle, CheckCircle, Clock, ScanBarcode,
  BookOpen, User, Loader2, X, ArrowRightLeft, BookmarkPlus,
  BookMarked, Bell, CheckCircle2, XCircle, Calendar, Send, RefreshCw, AlertTriangle
} from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Badge } from './ui/badge';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from './ui/table';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { client } from '../api/client';
import { useAuth } from '../contexts/AuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import { toast } from 'sonner';

export interface BorrowedBook {
  id: number;
  bookId: number;
  book: { title: string; author: string }; // Nested from Prisma include
  user: { name: string; email: string };   // Nested from Prisma include
  borrowDate: string;
  dueDate: string;
  status: 'On Time' | 'Overdue' | 'Due Soon' | 'Returned';
  renewalStatus?: 'NONE' | 'PENDING' | 'APPROVED' | 'REJECTED' | string;
}

interface BorrowedBooksProps {
  userRole?: 'ADMIN' | 'USER' | null;
  borrowedBooks?: any;
  onReturnBook?: any;
}

interface BarcodeLookupResult {
  bookItem: {
    id: number;
    barcode: string;
    location: string | null;
    status: string;
  };
  book: {
    id: number;
    title: string;
    isbn: string;
    author: string;
    category: string;
    publisher: string;
    coverImage: string | null;
  };
  activeLoan: {
    id: number;
    borrowDate: string;
    dueDate: string;
    status: string;
    user: { id: number; name: string; email: string };
  } | null;
}

export interface ReservationItem {
  id: number;
  userId: number;
  bookId: number;
  status: 'WAITING' | 'NOTIFIED' | 'FULFILLED' | 'CANCELLED';
  createdAt: string;
  user: {
    id: number;
    name: string;
    email: string;
    membershipTier?: string;
  } | null;
  book: {
    id: number;
    title: string;
    isbn: string;
    author: string;
    category: string;
    coverImage: string | null;
    available: number;
    totalCopies: number;
  } | null;
}

export function BorrowedBooks({ userRole: propUserRole }: BorrowedBooksProps = {}) {
  const { user: currentAdmin } = useAuth();
  const { t, language } = useLanguage();
  const userRole = propUserRole || currentAdmin?.role;
  const [searchParams, setSearchParams] = useSearchParams();
  const tabParam = searchParams.get('tab');
  const [activeTab, setActiveTab] = useState<'loans' | 'reservations'>(
    tabParam === 'reservations' ? 'reservations' : 'loans'
  );

  const [searchQuery, setSearchQuery] = useState('');
  const [barcodeInput, setBarcodeInput] = useState('');
  const [scanResult, setScanResult] = useState<BarcodeLookupResult | null>(null);
  const [scanError, setScanError] = useState('');
  const [scanMode, setScanMode] = useState<'borrow' | 'return'>('borrow');
  const [selectedUserId, setSelectedUserId] = useState<string>('');
  const [successMessage, setSuccessMessage] = useState('');
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  // Reservation filter states
  const [reservationSearch, setReservationSearch] = useState('');
  const [reservationFilter, setReservationFilter] = useState<'ALL' | 'WAITING' | 'NOTIFIED' | 'FULFILLED' | 'CANCELLED'>('ALL');

  // Lost / Compensation Modal states
  const [lostModalOpen, setLostModalOpen] = useState(false);
  const [selectedLoanForLost, setSelectedLoanForLost] = useState<any>(null);
  const [compensationAmount, setCompensationAmount] = useState<string>('50000');

  const queryClient = useQueryClient();

  useEffect(() => {
    if (tabParam === 'reservations') {
      setActiveTab('reservations');
    } else if (tabParam === 'loans') {
      setActiveTab('loans');
    }
  }, [tabParam]);

  const handleTabChange = (tab: 'loans' | 'reservations') => {
    setActiveTab(tab);
    setSearchParams(tab === 'reservations' ? { tab: 'reservations' } : {});
  };

  // Fetch Loans
  const { data: loans = [], isLoading } = useQuery({
    queryKey: ['all-loans'],
    queryFn: async () => {
      const { data } = await client.get('/loans/all');
      return data;
    }
  });

  // Fetch Reservations
  const { data: reservations = [], isLoading: isReservationsLoading } = useQuery({
    queryKey: ['all-reservations'],
    queryFn: async () => {
      const { data } = await client.get('/reservations/all');
      return data as ReservationItem[];
    },
    enabled: userRole === 'ADMIN'
  });

  // Fetch users list for borrower selection
  const { data: users = [] } = useQuery({
    queryKey: ['users'],
    queryFn: async () => {
      const { data } = await client.get('/auth/users');
      return data;
    }
  });

  // Return Book Mutation
  const returnMutation = useMutation({
    mutationFn: async (loanId: number) => {
      const { data } = await client.post('/loans/return', { loanId });
      return data;
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      if (data?.reservationNotice) {
        toast.success(`Thu hồi sách thành công! Độc giả ${data.reservationNotice.userName} đang đặt trước sách này. Trạng thái đã chuyển sang "Đã thông báo"!`, { duration: 5000 });
      } else {
        toast.success("Thu hồi sách thành công!");
      }
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || "Có lỗi xảy ra khi thu hồi sách");
    }
  });

  // Renew Loan Mutation
  const renewMutation = useMutation({
    mutationFn: async (loanId: number) => {
      const { data } = await client.post(`/loans/${loanId}/renew`);
      return data;
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      toast.success(data?.message || (language === 'vi' ? 'Gia hạn sách thành công thêm 7 ngày!' : 'Loan renewed successfully for 7 days!'));
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || (language === 'vi' ? 'Không thể gia hạn sách' : 'Failed to renew loan'));
    }
  });

  // Approve Renew Loan Mutation (Admin)
  const approveRenewMutation = useMutation({
    mutationFn: async (loanId: number) => {
      const { data } = await client.post(`/loans/${loanId}/approve-renew`);
      return data;
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      toast.success(data?.message || (language === 'vi' ? 'Đã phê duyệt gia hạn sách thêm 7 ngày!' : 'Loan renewal approved for 7 days!'));
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || (language === 'vi' ? 'Không thể phê duyệt gia hạn sách' : 'Failed to approve renewal'));
    }
  });

  // Reject Renew Loan Mutation (Admin)
  const rejectRenewMutation = useMutation({
    mutationFn: async (loanId: number) => {
      const { data } = await client.post(`/loans/${loanId}/reject-renew`);
      return data;
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      toast.success(data?.message || (language === 'vi' ? 'Đã từ chối yêu cầu gia hạn sách!' : 'Loan renewal rejected!'));
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || (language === 'vi' ? 'Không thể từ chối gia hạn sách' : 'Failed to reject renewal'));
    }
  });

  // Report Lost Mutation
  const reportLostMutation = useMutation({
    mutationFn: async ({ loanId, compensationAmount }: { loanId: number; compensationAmount: number }) => {
      const { data } = await client.post(`/loans/${loanId}/report-lost`, { compensationAmount });
      return data;
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      toast.success(data?.message || (language === 'vi' ? 'Báo mất sách và ghi nhận bồi thường thành công!' : 'Reported lost book and recorded compensation!'));
      setLostModalOpen(false);
      setSelectedLoanForLost(null);
      setCompensationAmount('50000');
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || (language === 'vi' ? 'Không thể xử lý báo mất sách' : 'Failed to report lost book'));
    }
  });

  // Barcode Lookup Mutation
  const lookupMutation = useMutation({
    mutationFn: async (barcode: string) => {
      const { data } = await client.get(`/loans/barcode/${encodeURIComponent(barcode.trim())}`);
      return data as BarcodeLookupResult;
    },
    onSuccess: (data) => {
      setScanResult(data);
      setScanError('');
      setSelectedUserId('');
      setSuccessMessage('');
    },
    onError: (error: any) => {
      setScanError(error.response?.data?.error || 'Không tìm thấy cuốn sách với mã vạch này');
      setScanResult(null);
    }
  });

  // Borrow by Barcode Mutation
  const borrowByBarcodeMutation = useMutation({
    mutationFn: async ({ barcode, userId }: { barcode: string; userId: number }) => {
      const { data } = await client.post('/loans/borrow-by-barcode', { barcode, userId });
      return data;
    },
    onSuccess: (data) => {
      setSuccessMessage(data.message || 'Cho mượn sách thành công!');
      setScanError('');
      setScanResult(null);
      setBarcodeInput('');
      setSelectedUserId('');
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      barcodeInputRef.current?.focus();
    },
    onError: (error: any) => {
      setScanError(error.response?.data?.error || 'Có lỗi khi cho mượn');
    }
  });

  // Return by Barcode Mutation
  const returnByBarcodeMutation = useMutation({
    mutationFn: async (barcode: string) => {
      const { data } = await client.post('/loans/return-by-barcode', { barcode });
      return data;
    },
    onSuccess: (data) => {
      setSuccessMessage(data.message || 'Thu hồi sách thành công!');
      setScanError('');
      setScanResult(null);
      setBarcodeInput('');
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      barcodeInputRef.current?.focus();
    },
    onError: (error: any) => {
      setScanError(error.response?.data?.error || 'Có lỗi khi thu hồi');
    }
  });

  // Update Reservation Status Mutation
  const updateReservationStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: number; status: string }) => {
      const { data } = await client.patch(`/reservations/${id}/status`, { status });
      return data;
    },
    onSuccess: (data) => {
      toast.success(data.message || 'Cập nhật trạng thái đặt trước thành công!');
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
      queryClient.invalidateQueries({ queryKey: ['books'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi cập nhật trạng thái đặt trước');
    }
  });

  // Cancel Reservation Mutation
  const cancelReservationMutation = useMutation({
    mutationFn: async (id: number) => {
      const { data } = await client.delete(`/reservations/${id}`);
      return data;
    },
    onSuccess: () => {
      toast.success('Đã hủy yêu cầu đặt trước thành công!');
      queryClient.invalidateQueries({ queryKey: ['all-reservations'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi hủy yêu cầu đặt trước');
    }
  });

  // Trigger Email Reminders Mutation
  const remindersMutation = useMutation({
    mutationFn: async () => {
      const { data } = await client.post('/loans/reminders/trigger');
      return data;
    },
    onSuccess: (data) => {
      toast.success(data.message || 'Đã hoàn tất quét và gửi email nhắc nhở!');
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi gửi email nhắc nhở');
    }
  });

  // Handle enter key on barcode input
  const handleBarcodeScan = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && barcodeInput.trim()) {
      e.preventDefault();
      setScanError('');
      setSuccessMessage('');
      lookupMutation.mutate(barcodeInput.trim());
    }
  };

  const handleClearScan = () => {
    setBarcodeInput('');
    setScanResult(null);
    setScanError('');
    setSuccessMessage('');
    setSelectedUserId('');
    barcodeInputRef.current?.focus();
  };

  const handleBorrowConfirm = () => {
    if (!scanResult || !selectedUserId) return;
    borrowByBarcodeMutation.mutate({
      barcode: scanResult.bookItem.barcode,
      userId: Number(selectedUserId)
    });
  };

  const handleReturnConfirm = () => {
    if (!scanResult) return;
    returnByBarcodeMutation.mutate(scanResult.bookItem.barcode);
  };

  const filteredLoans = loans.filter((loan: any) =>
    loan.book?.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    loan.user?.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    loan.user?.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
    loan.bookItem?.barcode?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredReservations = reservations.filter((r) => {
    const matchesSearch =
      (r.book?.title || '').toLowerCase().includes(reservationSearch.toLowerCase()) ||
      (r.book?.author || '').toLowerCase().includes(reservationSearch.toLowerCase()) ||
      (r.user?.name || '').toLowerCase().includes(reservationSearch.toLowerCase()) ||
      (r.user?.email || '').toLowerCase().includes(reservationSearch.toLowerCase()) ||
      (r.book?.isbn || '').toLowerCase().includes(reservationSearch.toLowerCase());

    const matchesStatus = reservationFilter === 'ALL' || r.status === reservationFilter;
    return matchesSearch && matchesStatus;
  });

  const waitingCount = reservations.filter(r => r.status === 'WAITING').length;
  const notifiedCount = reservations.filter(r => r.status === 'NOTIFIED').length;
  const fulfilledCount = reservations.filter(r => r.status === 'FULFILLED').length;

  if (isLoading) return <div className="p-8 text-center text-gray-500">Đang tải dữ liệu mượn trả...</div>;

  return (
    <div className="space-y-6">
      {/* Title & Navigation */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">{t('borrowed.title')}</h2>
          <p className="text-gray-500 dark:text-gray-400">{t('borrowed.subtitle')}</p>
        </div>

        {userRole === 'ADMIN' && (
          <Button
            onClick={() => remindersMutation.mutate()}
            disabled={remindersMutation.isPending}
            className="flex items-center gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white shadow-sm self-start sm:self-auto"
            title="Quét tìm sách sắp đến hạn (1-2 ngày) và quá hạn để gửi email nhắc nhở độc giả ngay lập tức"
          >
            {remindersMutation.isPending ? (
              <><Loader2 size={16} className="animate-spin" /> Đang quét & gửi email...</>
            ) : (
              <><Send size={16} /> Quét & Gửi email nhắc nhở</>
            )}
          </Button>
        )}
      </div>

      {/* Tabs Selector */}
      <div className="flex border-b border-gray-200 dark:border-gray-800 gap-2">
        <button
          onClick={() => handleTabChange('loans')}
          className={`flex items-center gap-2 pb-3 px-4 font-medium text-sm border-b-2 transition-all ${activeTab === 'loans'
              ? 'border-blue-600 text-blue-600 dark:text-blue-400 font-semibold'
              : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200'
            }`}
        >
          <BookMarked size={18} />
          <span>{t('borrowed.loansTab')}</span>
          <span className="ml-1 px-2 py-0.5 text-xs rounded-full bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300">
            {loans.filter((l: any) => l.status !== 'Returned').length}
          </span>
        </button>

        <button
          onClick={() => handleTabChange('reservations')}
          className={`flex items-center gap-2 pb-3 px-4 font-medium text-sm border-b-2 transition-all ${activeTab === 'reservations'
              ? 'border-amber-600 text-amber-600 dark:text-amber-400 font-semibold'
              : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200'
            }`}
        >
          <BookmarkPlus size={18} />
          <span>{t('borrowed.reservationsTab')}</span>
          {waitingCount > 0 && (
            <span className="ml-1 px-2 py-0.5 text-xs rounded-full bg-amber-500 text-white font-bold animate-pulse">
              {waitingCount}
            </span>
          )}
        </button>
      </div>

      {/* ================= TAB 1: LOANS MANAGEMENT & BARCODE ================= */}
      {activeTab === 'loans' && (
        <div className="space-y-6">
          {/* Barcode Scanner Panel */}
          {userRole === 'ADMIN' && (
            <div className="bg-gradient-to-r from-indigo-50 to-blue-50 dark:from-indigo-950/30 dark:to-blue-950/30 rounded-xl border border-indigo-200 dark:border-indigo-800 shadow-sm overflow-hidden">
              <div className="p-4 border-b border-indigo-200 dark:border-indigo-800 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <ScanBarcode className="text-indigo-600 dark:text-indigo-400" size={22} />
                  <h3 className="font-bold text-indigo-900 dark:text-indigo-200">Quét mã vạch sách</h3>
                </div>
                <div className="flex items-center gap-1 bg-white dark:bg-gray-800 rounded-lg p-1 border border-indigo-200 dark:border-indigo-700">
                  <button
                    onClick={() => { setScanMode('borrow'); handleClearScan(); }}
                    className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${scanMode === 'borrow'
                        ? 'bg-indigo-600 text-white shadow-sm'
                        : 'text-gray-600 dark:text-gray-400 hover:text-indigo-600'
                      }`}
                  >
                    Cho mượn
                  </button>
                  <button
                    onClick={() => { setScanMode('return'); handleClearScan(); }}
