import React, { useState, useRef } from 'react';
import {
  X, FileSpreadsheet, Download, UploadCloud, CheckCircle2,
  AlertTriangle, Loader2, Info, FileText, CheckCircle, AlertCircle
} from 'lucide-react';
import { Button } from './ui/button';
import { client } from '../api/client';
import { toast } from 'sonner';
import { useQueryClient } from '@tanstack/react-query';
import * as XLSX from 'xlsx';

interface ImportExcelModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

interface SkippedItem {
  row: number;
  title: string;
  isbn: string;
  reason: string;
}

interface ImportResult {
  success: boolean;
  message: string;
  importedCount: number;
  totalCopiesCreated?: number;
  skippedCount: number;
  imported: { title: string; isbn: string; copies: number }[];
  skipped: SkippedItem[];
  totalRows: number;
}

export function ImportExcelModal({ isOpen, onClose, onSuccess }: ImportExcelModalProps) {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<ImportResult | null>(null);
  const [isDownloadingTemplate, setIsDownloadingTemplate] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const queryClient = useQueryClient();

  if (!isOpen) return null;

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files && files.length > 0) {
      validateAndSetFile(files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      validateAndSetFile(files[0]);
    }
  };

  const validateAndSetFile = (file: File) => {
    if (!file.name.match(/\.(xlsx|xls)$/i)) {
      toast.error('Vui lòng chọn định dạng file Excel (.xlsx hoặc .xls)');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      toast.error('Kích thước file không được vượt quá 10MB');
      return;
    }
    setSelectedFile(file);
    setResult(null);
  };

  const handleDownloadTemplate = async () => {
    try {
      setIsDownloadingTemplate(true);
      // Try backend endpoint first
      try {
        const response = await client.get('/books/import-template', {
          responseType: 'blob'
        });
        const blobUrl = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement('a');
        link.href = blobUrl;
        link.setAttribute('download', 'mau_nhap_sach_thu_vien.xlsx');
        document.body.appendChild(link);
        link.click();
        link.remove();
        window.URL.revokeObjectURL(blobUrl);
        toast.success('Đã tải xuống file mẫu thành công!');
        return;
      } catch (err) {
        console.warn('Backend template download failed, generating client-side fallback:', err);
      }

      // Fallback: Generate client-side using xlsx
      const templateData = [
        {
          'Tiêu đề': 'Đắc Nhân Tâm',
          'Tác giả': 'Dale Carnegie',
          'Thể loại': 'Kỹ năng sống',
          'ISBN': '978-604-58-1234-5',
          'Số lượng bản sao': 5,
          'Nhà xuất bản': 'NXB Tổng Hợp TP.HCM',
          'Năm xuất bản': 2021,
          'Số trang': 320,
          'Ngôn ngữ': 'Tiếng Việt',
          'Mô tả': 'Nghệ thuật thu phục lòng người và giao tiếp ứng xử kinh điển.',
          'Ảnh bìa': 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&q=80&w=400'
        },
        {
          'Tiêu đề': 'Nhà Giả Kim',
          'Tác giả': 'Paulo Coelho',
          'Thể loại': 'Văn học nước ngoài',
          'ISBN': '978-604-58-6789-0',
          'Số lượng bản sao': 3,
          'Nhà xuất bản': 'NXB Hội Nhà Văn',
          'Năm xuất bản': 2020,
          'Số trang': 228,
          'Ngôn ngữ': 'Tiếng Việt',
          'Mô tả': 'Hành trình đi tìm kho báu và lắng nghe tiếng gọi của vũ trụ.',
          'Ảnh bìa': 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&q=80&w=400'
        },
        {
          'Tiêu đề': 'Clean Code: A Handbook of Agile Software Craftsmanship',
          'Tác giả': 'Robert C. Martin',
          'Thể loại': 'Công nghệ thông tin',
          'ISBN': '978-013-23-5088-4',
          'Số lượng bản sao': 4,
          'Nhà xuất bản': 'Prentice Hall',
          'Năm xuất bản': 2008,
          'Số trang': 464,
          'Ngôn ngữ': 'Tiếng Anh',
          'Mô tả': 'Cẩm nang viết mã sạch và tư duy kỹ thuật phần mềm chuẩn mực.',
          'Ảnh bìa': 'https://images.unsplash.com/photo-1532012164546-f432f2e3777a?auto=format&fit=crop&q=80&w=400'
        }
      ];

      const worksheet = XLSX.utils.json_to_sheet(templateData);
      worksheet['!cols'] = [
        { wch: 35 }, { wch: 22 }, { wch: 22 }, { wch: 22 }, { wch: 18 },
        { wch: 26 }, { wch: 15 }, { wch: 12 }, { wch: 15 }, { wch: 45 }, { wch: 35 }
      ];

      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, 'MauNhapSach');
      XLSX.writeFile(workbook, 'mau_nhap_sach_thu_vien.xlsx');
      toast.success('Đã tải xuống file mẫu thành công!');
    } catch (error) {
      console.error('Error generating template:', error);
      toast.error('Không thể tạo file mẫu');
    } finally {
      setIsDownloadingTemplate(false);
    }
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      toast.error('Vui lòng chọn một file Excel (.xlsx hoặc .xls)');
      return;
    }

    try {
      setIsLoading(true);
      const formData = new FormData();
      formData.append('file', selectedFile);

      const { data } = await client.post('/books/import', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      setResult(data);

      // Invalidate all related caches
      queryClient.invalidateQueries({ queryKey: ['books'] });
      queryClient.invalidateQueries({ queryKey: ['book-recommendations'] });
      queryClient.invalidateQueries({ queryKey: ['analytics-stats'] });
      queryClient.invalidateQueries({ queryKey: ['top-books'] });
      queryClient.invalidateQueries({ queryKey: ['all-loans'] });

      const copiesText = data.totalCopiesCreated ? ` (${data.totalCopiesCreated} cuốn bản sao)` : '';
      const skippedText = data.skippedCount > 0 ? `, bỏ qua ${data.skippedCount} cuốn do trùng mã hoặc lỗi` : '';
      const toastMsg = data.message || `Đã thêm thành công ${data.importedCount || 0} đầu sách${copiesText}${skippedText}`;

      if (data.skippedCount > 0 && data.importedCount === 0) {
        toast.warning(toastMsg, { duration: 6000 });
      } else {
        toast.success(toastMsg, { duration: 6000 });
      }

      if (onSuccess) onSuccess();
    } catch (error: any) {
      console.error('Error uploading file:', error);
      const errMsg = error.response?.data?.error || error.message || 'Có lỗi xảy ra khi tải file lên';
      toast.error(errMsg);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    setSelectedFile(null);
    setResult(null);
    setIsLoading(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs animate-in fade-in duration-200">
      <div 
        className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl shadow-2xl w-full max-w-2xl max-h-[92vh] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-gray-800/40">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-emerald-100 dark:bg-emerald-950/60 text-emerald-600 dark:text-emerald-400 rounded-xl">
              <FileSpreadsheet size={24} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">
                Thêm sách hàng loạt từ file Excel (Bulk Import)
              </h3>
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                Nhập kho nhiều đầu sách tự động, tạo bản sao vật lý và gắn barcode chuẩn hóa.
              </p>
            </div>
          </div>
          <button
            onClick={handleClose}
            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Content Body */}
        <div className="p-6 overflow-y-auto space-y-5 flex-1">
          {/* Template Download Card */}
          <div className="p-4 bg-blue-50/70 dark:bg-blue-950/30 border border-blue-200/80 dark:border-blue-800/50 rounded-xl flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <Info size={16} className="text-blue-600 dark:text-blue-400" />
                <h4 className="text-sm font-semibold text-blue-900 dark:text-blue-200">
                  File mẫu chuẩn định dạng
                </h4>
              </div>
              <p className="text-xs text-blue-700 dark:text-blue-300">
                Bao gồm các cột: <strong>Tiêu đề</strong>, <strong>Tác giả</strong>, <strong>Thể loại</strong>, <strong>ISBN</strong>, <strong>Số lượng bản sao</strong>, NXB, Năm XB...
              </p>
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleDownloadTemplate}
              disabled={isDownloadingTemplate}
              className="gap-2 bg-white dark:bg-gray-800 hover:bg-blue-50 border-blue-200 dark:border-blue-700 text-blue-700 dark:text-blue-300 font-semibold shrink-0 shadow-xs"
            >
              {isDownloadingTemplate ? (
                <Loader2 size={15} className="animate-spin" />
              ) : (
                <Download size={15} />
              )}
              Tải file mẫu (Template)
            </Button>
          </div>

          {/* Upload / Drag & Drop Area */}
          {!result && (
            <div>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileSelect}
                accept=".xlsx,.xls"
                className="hidden"
              />

              {!selectedFile ? (
                <div
                  onDragOver={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                  onClick={() => fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all flex flex-col items-center justify-center gap-3 ${
                    isDragging
                      ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-950/20'
                      : 'border-gray-300 dark:border-gray-700 hover:border-emerald-500 hover:bg-gray-50/60 dark:hover:bg-gray-800/40'
                  }`}
                >
                  <div className="p-3 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400 rounded-full">
                    <UploadCloud size={32} />
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-800 dark:text-gray-200">
                      Kéo thả file Excel vào đây hoặc <span className="text-emerald-600 hover:underline">duyệt tìm file</span>
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                      Hỗ trợ định dạng .xlsx, .xls (Kích thước tối đa 10MB)
                    </p>
                  </div>
                </div>
              ) : (
                <div className="p-4 border border-emerald-200 dark:border-emerald-900 bg-emerald-50/40 dark:bg-emerald-950/20 rounded-xl flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3 overflow-hidden">
                    <div className="p-2.5 bg-emerald-100 dark:bg-emerald-900/60 text-emerald-700 dark:text-emerald-300 rounded-lg shrink-0">
                      <FileText size={22} />
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-semibold text-gray-900 dark:text-white truncate">
                        {selectedFile.name}
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {(selectedFile.size / 1024).toFixed(1)} KB • Sẵn sàng import
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => fileInputRef.current?.click()}
                      disabled={isLoading}
                      className="text-xs"
                    >
                      Đổi file
                    </Button>
                    <button
                      type="button"
                      onClick={() => setSelectedFile(null)}
                      disabled={isLoading}
                      className="text-gray-400 hover:text-red-500 p-1.5 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
                    >
                      <X size={16} />
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Results Summary after Import */}
          {result && (
            <div className="space-y-4 animate-in fade-in duration-300">
              {/* Summary Card */}
              <div className="p-4 rounded-xl border bg-gray-50 dark:bg-gray-800/60 border-gray-200 dark:border-gray-700">
                <div className="flex items-start gap-3">
                  {result.importedCount > 0 ? (
                    <CheckCircle2 size={22} className="text-emerald-600 dark:text-emerald-400 shrink-0 mt-0.5" />
                  ) : (
                    <AlertTriangle size={22} className="text-amber-600 dark:text-amber-400 shrink-0 mt-0.5" />
                  )}
                  <div>
                    <h4 className="text-sm font-bold text-gray-900 dark:text-white">
                      {result.message}
                    </h4>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                      Tổng số dòng: {result.totalRows} | Thành công: <strong className="text-emerald-600">{result.importedCount}</strong> đầu sách ({result.totalCopiesCreated || 0} bản sao) | Bỏ qua: <strong className="text-rose-600">{result.skippedCount}</strong> cuốn
                    </p>
                  </div>
                </div>
              </div>

              {/* List of Skipped Books (Duplicates / Errors) */}
              {result.skipped && result.skipped.length > 0 && (
                <div className="border border-amber-200 dark:border-amber-900/50 rounded-xl overflow-hidden">
                  <div className="bg-amber-50 dark:bg-amber-950/30 px-4 py-2.5 border-b border-amber-200 dark:border-amber-900/50 flex items-center justify-between">
                    <span className="text-xs font-bold text-amber-800 dark:text-amber-300 flex items-center gap-1.5">
                      <AlertCircle size={14} /> Danh sách bỏ qua ({result.skipped.length} cuốn)
                    </span>
                    <span className="text-[11px] text-amber-700 dark:text-amber-400">
                      Do trùng mã ISBN hoặc thiếu thông tin
                    </span>
                  </div>
                  <div className="max-h-48 overflow-y-auto divide-y divide-amber-100 dark:divide-amber-950/40 p-2 text-xs">
                    {result.skipped.map((item, idx) => (
                      <div key={idx} className="p-2 space-y-0.5 hover:bg-amber-50/50 dark:hover:bg-amber-950/20 rounded">
                        <div className="flex items-center justify-between">
                          <span className="font-semibold text-gray-900 dark:text-white">
                            Dòng {item.row}: {item.title}
                          </span>
                          <span className="font-mono text-[11px] text-gray-500">
                            ISBN: {item.isbn}
                          </span>
                        </div>
                        <p className="text-[11px] text-amber-700 dark:text-amber-400">
                          Lý do: {item.reason}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* List of Imported Books */}
              {result.imported && result.imported.length > 0 && (
                <div className="border border-emerald-200 dark:border-emerald-900/50 rounded-xl overflow-hidden">
                  <div className="bg-emerald-50 dark:bg-emerald-950/30 px-4 py-2.5 border-b border-emerald-200 dark:border-emerald-900/50 flex items-center justify-between">
                    <span className="text-xs font-bold text-emerald-800 dark:text-emerald-300 flex items-center gap-1.5">
                      <CheckCircle size={14} /> Danh sách đã thêm ({result.imported.length} đầu sách)
                    </span>
                  </div>
                  <div className="max-h-40 overflow-y-auto divide-y divide-emerald-100 dark:divide-emerald-950/40 p-2 text-xs">
                    {result.imported.map((item, idx) => (
                      <div key={idx} className="p-2 flex items-center justify-between hover:bg-emerald-50/50 dark:hover:bg-emerald-950/20 rounded">
                        <span className="font-medium text-gray-900 dark:text-white truncate pr-4">
                          {item.title}
                        </span>
                        <span className="text-[11px] text-emerald-700 dark:text-emerald-400 shrink-0 font-medium">
                          {item.copies} cuốn
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-5 border-t border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-gray-800/40 flex items-center justify-end gap-3">
          <Button
            type="button"
            variant="outline"
            onClick={handleClose}
            disabled={isLoading}
          >
            {result ? 'Đóng' : 'Hủy'}
          </Button>

          {!result ? (
            <Button
              type="button"
              onClick={handleUpload}
              disabled={!selectedFile || isLoading}
              className="gap-2 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold"
            >
              {isLoading ? (
                <>
                  <Loader2 size={16} className="animate-spin" />
                  Đang xử lý import...
                </>
              ) : (
                <>
                  <FileSpreadsheet size={16} />
                  Bắt đầu Import
                </>
              )}
            </Button>
          ) : (
            <Button
              type="button"
              onClick={() => {
                setSelectedFile(null);
                setResult(null);
              }}
              variant="outline"
              className="gap-1.5 text-emerald-600 border-emerald-200 hover:bg-emerald-50 dark:border-emerald-800 dark:text-emerald-400"
            >
              <UploadCloud size={15} />
              Import tiếp file khác
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { client } from '../api/client';
import { toast } from 'sonner';
import * as XLSX from 'xlsx';
import jsPDFInstance, { jsPDF } from 'jspdf';
import {
  ClipboardCheck,
  QrCode,
  ScanLine,
  CheckCircle2,
  AlertTriangle,
  HelpCircle,
  FileSpreadsheet,
  Download,
  RotateCcw,
  Search,
  Trash2,
  Layers,
  ArrowRight,
  TrendingUp,
  FileText,
  Eye,
  Barcode,
  MapPin,
  X
} from 'lucide-react';

interface ExpectedItem {
  id: number;
  barcode: string;
  location: string;
  status: string;
  bookTitle: string;
  isbn: string;
  author: string;
  category: string;
  coverImage?: string;
}

interface VerificationResult {
  summary: {
    totalExpected: number;
    totalScanned: number;
    matchedCount: number;
    missingCount: number;
    anomalousCount: number;
    accuracyRate: string;
    checkedAt: string;
  };
  matched: Array<{
    id: number;
    barcode: string;
    bookTitle: string;
    author: string;
    category: string;
    location: string;
    status: string;
  }>;
  missing: Array<{
    id: number;
    barcode: string;
    bookTitle: string;
    author: string;
    category: string;
    location: string;
    status: string;
  }>;
  anomalous: Array<{
    id?: number;
    barcode: string;
    issueType: string;
    reason: string;
    bookTitle: string;
    author: string;
    location: string;
    dbStatus: string;
  }>;
}

export function InventoryCheck() {
  const [barcodeInput, setBarcodeInput] = useState('');
  const [scannedList, setScannedList] = useState<string[]>([]);
  const [activeResultTab, setActiveResultTab] = useState<'MATCHED' | 'MISSING' | 'ANOMALOUS'>('MATCHED');
  const [result, setResult] = useState<VerificationResult | null>(null);

  // States cho Modal Xem chi tiết kho dự kiến
  const [showExpectedModal, setShowExpectedModal] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const barcodeInputRef = useRef<HTMLInputElement>(null);

  // Fetch expected AVAILABLE inventory from database
  const { data: expectedData, isLoading: isLoadingExpected, refetch: refetchExpected } = useQuery<{
    total: number;
    items: ExpectedItem[];
  }>({
    queryKey: ['inventory-expected'],
    queryFn: async () => {
      const { data } = await client.get('/inventory/expected');
      return data;
    }
  });

  const expectedTotal = expectedData?.total || 0;

  // Lọc nhanh danh sách sách dự kiến theo tên sách, mã vạch, tác giả hoặc vị trí
  const filteredExpectedItems = (expectedData?.items || []).filter((item) => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      item.bookTitle.toLowerCase().includes(q) ||
      item.barcode.toLowerCase().includes(q) ||
      (item.author && item.author.toLowerCase().includes(q)) ||
      (item.location && item.location.toLowerCase().includes(q)) ||
      (item.category && item.category.toLowerCase().includes(q))
    );
  });

  // Đóng modal và tự động focus lại ô quét mã vạch
  const handleCloseExpectedModal = () => {
    setShowExpectedModal(false);
    setSearchQuery('');
    setTimeout(() => {
      barcodeInputRef.current?.focus();
    }, 100);
  };

  // Auto focus input on mount and whenever user clicks outside
  useEffect(() => {
    barcodeInputRef.current?.focus();
  }, []);

  // Web Audio Beep sound on scan
  const playScanBeep = (isError = false) => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.type = 'sine';
      osc.frequency.value = isError ? 300 : 900;
      gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.15);
    } catch {
      // AudioContext may be restricted by browser policy
    }
  };

  // Add barcode on Enter (Bar-code scanner trigger)
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const code = barcodeInput.trim().toUpperCase();
      if (!code) return;

      if (scannedList.includes(code)) {
        playScanBeep(true);
        toast.warning(`Mã vạch "${code}" đã được quét trước đó trong đợt này!`);
      } else {
        playScanBeep(false);
        setScannedList(prev => [code, ...prev]);
        toast.success(`Đã ghi nhận mã vạch: ${code}`);
      }

      setBarcodeInput('');
      barcodeInputRef.current?.focus();
    }
  };

  const handleRemoveScanned = (codeToRemove: string) => {
    setScannedList(prev => prev.filter(c => c !== codeToRemove));
  };

  const handleResetSession = () => {
    if (scannedList.length === 0 && !result) return;
    if (confirm('Bạn có chắc chắn muốn làm mới đợt kiểm kê này và xóa toàn bộ danh sách đã quét?')) {
      setScannedList([]);
      setResult(null);
      setBarcodeInput('');
      barcodeInputRef.current?.focus();
      toast.info('Đã làm mới phiên kiểm kê');
    }
  };

  // Verification Mutation
  const verifyMutation = useMutation({
    mutationFn: async (barcodes: string[]) => {
      const { data } = await client.post('/inventory/verify', {
        scannedBarcodes: barcodes
      });
      return data as VerificationResult;
    },
    onSuccess: (data) => {
      setResult(data);
      toast.success('Đã hoàn tất đối chiếu kiểm kê kho sách!');
      if (data.missing.length > 0 || data.anomalous.length > 0) {
        setActiveResultTab('MISSING');
      } else {
        setActiveResultTab('MATCHED');
      }
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.error || 'Có lỗi khi đối chiếu kiểm kê');
    }
  });

  const handleVerify = () => {
    if (scannedList.length === 0) {
      toast.error('Vui lòng quét ít nhất một mã vạch trước khi đối chiếu');
      barcodeInputRef.current?.focus();
      return;
    }
    verifyMutation.mutate(scannedList);
  };

  // Export to Excel (.xlsx)
  const handleExportExcel = () => {
    if (!result) {
      toast.error('Chưa có kết quả đối chiếu để xuất báo cáo');
      return;
    }

    try {
      const wb = XLSX.utils.book_new();

      // Sheet 1: Tổng hợp
      const summaryData = [
        ['BÁO CÁO KIỂM KÊ KHO SÁCH ĐỊNH KỲ'],
        ['Thời gian lập biểu:', new Date(result.summary.checkedAt).toLocaleString('vi-VN')],
        [''],
        ['Chỉ số', 'Số lượng', 'Tỷ lệ'],
        ['Tổng sách dự kiến trên kệ (AVAILABLE)', result.summary.totalExpected, '100%'],
        ['Tổng mã vạch quét được thực tế', result.summary.totalScanned, ''],
        ['Sách hợp lệ (Đúng vị trí trên kệ)', result.summary.matchedCount, `${result.summary.accuracyRate}%`],
        ['Sách bị thiếu (Thất lạc / chưa quét)', result.summary.missingCount, ''],
        ['Sách bất thường (Sai trạng thái / Mã lạ)', result.summary.anomalousCount, '']
      ];
      const wsSummary = XLSX.utils.aoa_to_sheet(summaryData);
      XLSX.utils.book_append_sheet(wb, wsSummary, 'Tổng Quan');

      // Sheet 2: Sách hợp lệ
      const matchedData = result.matched.map((item, idx) => ({
        'STT': idx + 1,
        'Mã vạch (Barcode)': item.barcode,
        'Tên sách': item.bookTitle,
        'Tác giả': item.author,
        'Thể loại': item.category,
        'Vị trí kệ': item.location,
        'Kết quả': 'HỢP LỆ'
      }));
      const wsMatched = XLSX.utils.json_to_sheet(matchedData);
      XLSX.utils.book_append_sheet(wb, wsMatched, 'Sách Hợp Lệ');

      // Sheet 3: Sách bị thiếu
      const missingData = result.missing.map((item, idx) => ({
        'STT': idx + 1,
        'Mã vạch (Barcode)': item.barcode,
        'Tên sách': item.bookTitle,
        'Tác giả': item.author,
        'Thể loại': item.category,
        'Vị trí kệ dự kiến': item.location,
        'Ghi chú': 'Không quét được trên kệ (Cần kiểm tra)'
      }));
      const wsMissing = XLSX.utils.json_to_sheet(missingData);
      XLSX.utils.book_append_sheet(wb, wsMissing, 'Sách Bị Thiếu');

      // Sheet 4: Sách bất thường
      const anomalousData = result.anomalous.map((item, idx) => ({
        'STT': idx + 1,
        'Mã vạch (Barcode)': item.barcode,
        'Tên sách': item.bookTitle,
        'Trạng thái CSDL': item.dbStatus,
        'Vị trí': item.location,
        'Chi tiết cảnh báo': item.reason
      }));
      const wsAnomalous = XLSX.utils.json_to_sheet(anomalousData);
      XLSX.utils.book_append_sheet(wb, wsAnomalous, 'Sách Bất Thường');

      const dateStr = new Date().toISOString().split('T')[0];
      XLSX.writeFile(wb, `Bao-Cao-Kiem-Ke-Kho-${dateStr}.xlsx`);
      toast.success('Đã xuất báo cáo Excel thành công!');
    } catch (err: any) {
      console.error(err);
      toast.error('Lỗi khi xuất file Excel');
    }
  };

  // Export to PDF
  const handleExportPDF = () => {
    if (!result) {
      toast.error('Chưa có kết quả đối chiếu để xuất báo cáo');
      return;
    }

    try {
      const Constructor = (jsPDF as any) || (jsPDFInstance as any)?.jsPDF || (jsPDFInstance as any)?.default || jsPDFInstance;
      const doc = new (Constructor as any)();
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(16);
      doc.text('THU VIEN PKA - BIEN BAN KIEM KE KHO SACH', 20, 20);

      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(10);
      doc.text(`Ngay kiem ke: ${new Date(result.summary.checkedAt).toLocaleString('vi-VN')}`, 20, 28);
      doc.text(`Tong so sach du kien (Available): ${result.summary.totalExpected}`, 20, 36);
      doc.text(`Tong so ma vach da quet: ${result.summary.totalScanned}`, 20, 42);
      doc.text(`Sach hop le: ${result.summary.matchedCount}`, 20, 48);
      doc.text(`Sach thieu tren ke: ${result.summary.missingCount}`, 20, 54);
      doc.text(`Sach bat thuong / sai trang thai: ${result.summary.anomalousCount}`, 20, 60);
      doc.text(`Ty le khop kho: ${result.summary.accuracyRate}%`, 20, 66);

      doc.setFont('Helvetica', 'bold');
      doc.text('DANH SACH CAN XU LY (SACH THIEU & BAT THUONG):', 20, 80);

      doc.setFont('Helvetica', 'normal');
      let y = 88;
      const combinedIssues = [
        ...result.missing.map(m => `[THIEU] ${m.barcode} - ${m.bookTitle.slice(0, 35)} (${m.location})`),
        ...result.anomalous.map(a => `[BAT THUONG: ${a.dbStatus}] ${a.barcode} - ${a.bookTitle.slice(0, 30)}`)
      ];

      if (combinedIssues.length === 0) {
        doc.text('Kho sach hoan hao, khong co sach thieu hoac bat thuong!', 20, y);
      } else {
        combinedIssues.slice(0, 25).forEach((line) => {
          if (y > 270) {
            doc.addPage();
            y = 20;
          }
          doc.text(line, 20, y);
          y += 7;
        });
      }

      const dateStr = new Date().toISOString().split('T')[0];
      doc.save(`Bien-Ban-Kiem-Ke-${dateStr}.pdf`);
      toast.success('Đã xuất biên bản kiểm kê PDF thành công!');
    } catch (err: any) {
      console.error(err);
      toast.error('Lỗi khi xuất file PDF');
    }
  };

  const progressPercent = expectedTotal > 0
    ? Math.min(100, Math.round((scannedList.length / expectedTotal) * 100))
    : 0;

  return (
    <div className="space-y-6 animate-in fade-in duration-300 pb-12">
      {/* Page Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
            <ClipboardCheck className="text-blue-600 dark:text-blue-400" />
            Kiểm kê kho sách định kỳ
          </h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            Quét mã vạch thực tế trên kệ để tự động đối chiếu dữ liệu tồn kho, phát hiện sách mất và sai trạng thái
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={handleResetSession}
            className="flex items-center gap-1.5 px-3.5 py-2 bg-gray-100 hover:bg-gray-200 dark:bg-gray-800 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 text-xs font-medium rounded-lg transition-colors border border-gray-200 dark:border-gray-700"
            title="Làm mới toàn bộ danh sách đã quét"
          >
            <RotateCcw size={15} />
            <span>Làm mới</span>
          </button>

          {result && (
            <>
              <button
                onClick={handleExportExcel}
                className="flex items-center gap-1.5 px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold rounded-lg shadow-sm transition-all active:scale-95"
              >
                <FileSpreadsheet size={15} />
                <span>Xuất Excel (.xlsx)</span>
              </button>

              <button
                onClick={handleExportPDF}
                className="flex items-center gap-1.5 px-3.5 py-2 bg-rose-600 hover:bg-rose-700 text-white text-xs font-semibold rounded-lg shadow-sm transition-all active:scale-95"
              >
                <FileText size={15} />
                <span>Xuất Báo cáo PDF</span>
              </button>
            </>
          )}
        </div>
      </div>

      {/* Progress & Stat Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm relative group">
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Sách dự kiến trên kệ</span>
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => setShowExpectedModal(true)}
                className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-100 dark:hover:bg-blue-900/50 rounded-lg transition-colors cursor-pointer"
                title="Xem danh sách chi tiết các mã vạch dự kiến trong kho"
              >
                <Eye size={13} />
                <span>Xem chi tiết</span>
              </button>
              <span className="p-1.5 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg">
                <Layers size={16} />
              </span>
            </div>
          </div>
          <p className="text-2xl font-bold text-gray-900 dark:text-white mt-2">
            {isLoadingExpected ? '...' : expectedTotal}
          </p>
          <div className="flex items-center justify-between mt-1">
            <p className="text-[11px] text-gray-400">Trạng thái AVAILABLE trong CSDL</p>
            <button
              type="button"
              onClick={() => setShowExpectedModal(true)}
              className="text-[11px] font-medium text-blue-500 hover:underline cursor-pointer"
            >
              Danh sách chi tiết &rarr;
            </button>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm">
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Đã quét thực tế</span>
            <span className="p-2 bg-indigo-50 dark:bg-indigo-950/40 text-indigo-600 dark:text-indigo-400 rounded-lg">
              <QrCode size={18} />
            </span>
          </div>
          <p className="text-2xl font-bold text-indigo-600 dark:text-indigo-400 mt-2">
            {scannedList.length}
          </p>
          <p className="text-[11px] text-gray-400 mt-1">Mã vạch duy nhất trong đợt này</p>
        </div>

        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm">
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Tiến độ quét kho</span>
            <span className="p-2 bg-amber-50 dark:bg-amber-950/30 text-amber-600 dark:text-amber-400 rounded-lg">
              <TrendingUp size={18} />
            </span>
          </div>
          <p className="text-2xl font-bold text-amber-600 dark:text-amber-400 mt-2">
            {progressPercent}%
          </p>
          <div className="w-full bg-gray-100 dark:bg-gray-800 rounded-full h-2 mt-2 overflow-hidden">
            <div
              className="bg-amber-500 h-2 rounded-full transition-all duration-300"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>
      </div>

      {/* Barcode Scanner Section */}
