                        </td>
                        <td className="py-3 px-4 text-center">
                          <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800/40">
                            <CheckCircle2 size={12} />
                            AVAILABLE
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-3.5 bg-gray-50 dark:bg-gray-800/50 border-t border-gray-200 dark:border-gray-800 flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">
                Mẹo: Bấm phím <kbd className="px-1.5 py-0.5 text-[11px] font-mono bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded shadow-xs">Esc</kbd> để đóng và tiếp tục quét mã vạch
              </span>
              <button
                type="button"
                onClick={handleCloseExpectedModal}
                className="px-4 py-2 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-800 dark:text-white rounded-xl text-xs font-semibold transition-colors cursor-pointer"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { client } from '../api/client';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, User, ArrowRight, KeyRound, X, Loader2, ShieldCheck, ArrowLeft } from 'lucide-react';
import { toast } from 'sonner';

interface LoginProps {
  onLogin?: (token: string, user: any) => void;
  onRegister?: (name: string, email: string, password: string) => void;
}

export function Login({ }: LoginProps) {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);

  // States cho tính năng Đăng nhập bảo mật 2 lớp (2FA / OTP Verification Modal)
  const [showOtpModal, setShowOtpModal] = useState(false);
  const [tempUserId, setTempUserId] = useState<number | null>(() => {
    const saved = localStorage.getItem('tempUserId');
    return saved ? Number(saved) : null;
  });
  const [loginOtp, setLoginOtp] = useState('');
  const [otpVerifying, setOtpVerifying] = useState(false);
  const [otpResending, setOtpResending] = useState(false);
  const [otpPreviewUrl, setOtpPreviewUrl] = useState<string | null>(null);

  // States cho tính năng Quên mật khẩu (Forgot Password Modal)
  const [showForgotModal, setShowForgotModal] = useState(false);
  const [forgotStep, setForgotStep] = useState<1 | 2>(1);
  const [forgotEmail, setForgotEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [otpSending, setOtpSending] = useState(false);
  const [resetting, setResetting] = useState(false);

  const { login } = useAuth();
  const navigate = useNavigate();

  /**
   * Xử lý đăng nhập / đăng ký
   * Nếu Backend yêu cầu OTP: TUYỆT ĐỐI KHÔNG set isAuthenticated, chỉ lưu tempUserId và mở popup OTP
   */
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (isRegistering) {
        await client.post('/auth/register', { email, password, name });
        toast.success('Đăng ký tài khoản thành công! Vui lòng đăng nhập.');
        setIsRegistering(false);
        return;
      }

      // Gọi API đăng nhập
      const { data } = await client.post('/auth/login', { email, password });

      // NẾU BACKEND YÊU CẦU OTP
      if (data.requireOtp) {
        // KHÔNG set isAuthenticated = true
        // KHÔNG lưu bất kỳ token nào vào localStorage
        // Chỉ lưu tempUserId để phục vụ bước verify
        localStorage.setItem('tempUserId', String(data.tempUserId));
        setTempUserId(data.tempUserId);
        setLoginOtp('');
        setOtpPreviewUrl(data.previewUrl || null);
        setShowOtpModal(true);
        toast.info(data.message || 'Tài khoản yêu cầu xác thực 2 lớp (OTP). Vui lòng kiểm tra email!');
        return;
      }

      // NẾU KHÔNG CẦN OTP
      if (data.token && data.user) {
        login(data.token, data.user);
        toast.success(`Chào mừng ${data.user.name || 'bạn'} đã đăng nhập thành công!`);
        if (data.user.role === 'ADMIN') {
          navigate('/');
        } else {
          navigate('/profile');
        }
      }
    } catch (error: any) {
      console.error(error);
      toast.error(error.response?.data?.error || 'Đăng nhập thất bại. Vui lòng kiểm tra lại thông tin!');
    } finally {
      setLoading(false);
    }
  };

  /**
   * Đóng popup OTP: Đảm bảo MỌI state liên quan đến đăng nhập bị reset sạch sẽ.
   * Khi bấm đăng nhập lại, luồng phải gọi lại API login từ đầu và tiếp tục bị chặn nếu chưa xác thực OTP.
   */
  const handleCloseOtpModal = () => {
    setShowOtpModal(false);
    setLoginOtp('');
    setTempUserId(null);
    setOtpPreviewUrl(null);
    localStorage.removeItem('tempUserId');
    localStorage.removeItem('token');
  };

  /**
   * Xác thực mã OTP: Khi API verify-otp trả về thành công kèm Token thật,
   * lúc này mới lưu Token vào localStorage và redirect vào trang chủ theo Role.
   */
  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginOtp.trim()) {
      toast.error('Vui lòng nhập mã OTP 6 chữ số');
      return;
    }

    const currentTempUserId = tempUserId || Number(localStorage.getItem('tempUserId'));
    if (!currentTempUserId) {
      toast.error('Phiên xác thực không hợp lệ hoặc đã hết hạn. Vui lòng đăng nhập lại.');
      handleCloseOtpModal();
      return;
    }

    setOtpVerifying(true);
    try {
      const { data } = await client.post('/auth/verify-otp', {
        tempUserId: currentTempUserId,
        otp: loginOtp.trim(),
      });

      // API trả về thành công kèm token thật và user
      if (data.token && data.user) {
        // Dọn dẹp trạng thái tạm thời
        localStorage.removeItem('tempUserId');
        setShowOtpModal(false);
        setLoginOtp('');
        setTempUserId(null);
        setOtpPreviewUrl(null);

        // Lưu Token và User vào localStorage thông qua AuthContext
        login(data.token, data.user);

        toast.success(`Xác thực OTP thành công! Chào mừng ${data.user.name || 'bạn'}`);

        // Chuyển hướng theo Role
        if (data.user.role === 'ADMIN') {
          navigate('/');
        } else {
          navigate('/profile');
        }
      } else {
        toast.error('Dữ liệu xác thực không hợp lệ. Vui lòng thử lại.');
      }
    } catch (error: any) {
      console.error(error);
      toast.error(error.response?.data?.error || 'Mã OTP không chính xác hoặc đã hết hạn.');
    } finally {
      setOtpVerifying(false);
    }
  };

  /**
   * Gửi lại mã OTP đăng nhập
   */
  const handleResendLoginOtp = async () => {
    const currentTempUserId = tempUserId || Number(localStorage.getItem('tempUserId'));
    if (!currentTempUserId) return;

    setOtpResending(true);
    const toastId = toast.loading('Đang gửi lại mã OTP...');
    try {
      const { data } = await client.post('/auth/resend-otp', {
        tempUserId: currentTempUserId,
      });
      if (data.previewUrl) setOtpPreviewUrl(data.previewUrl);
      toast.success(data.message || 'Đã gửi lại mã OTP đến email của bạn!', { id: toastId });
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Không thể gửi lại mã OTP', { id: toastId });
    } finally {
      setOtpResending(false);
    }
  };

  // Bước 1: Gửi mã OTP về email
  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!forgotEmail.trim()) {
      toast.error('Vui lòng nhập địa chỉ email của bạn');
      return;
    }

    setOtpSending(true);
    const toastId = toast.loading('Đang tạo và gửi mã OTP qua email...');
    try {
      const { data } = await client.post('/auth/forgot-password', { email: forgotEmail.trim() });
      toast.success(data.message || 'Mã xác thực OTP đã được gửi đến email!', { id: toastId });
      setForgotStep(2);
    } catch (error: any) {
      console.error(error);
      toast.error(error.response?.data?.error || 'Không thể gửi mã OTP. Vui lòng kiểm tra lại email!', { id: toastId });
    } finally {
      setOtpSending(false);
    }
  };

  // Bước 2: Xác nhận OTP và đặt lại mật khẩu mới
  const handleResetPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!otp.trim()) {
      toast.error('Vui lòng nhập mã OTP 6 chữ số');
      return;
    }
    if (newPassword.length < 6) {
      toast.error('Mật khẩu mới phải có tối thiểu 6 ký tự');
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error('Mật khẩu xác nhận không khớp. Vui lòng kiểm tra lại');
      return;
    }

    setResetting(true);
    const toastId = toast.loading('Đang xử lý đổi mật khẩu...');
    try {
      const { data } = await client.post('/auth/reset-password', {
        email: forgotEmail.trim(),
        otp: otp.trim(),
        newPassword
      });
      toast.success(data.message || 'Đổi mật khẩu thành công! Bạn có thể đăng nhập ngay.', { id: toastId });

      // Đóng modal và reset form
      setShowForgotModal(false);
      setForgotStep(1);
      setOtp('');
      setNewPassword('');
      setConfirmPassword('');
      // Điền sẵn email vừa đổi vào form đăng nhập để tiện thao tác
      setEmail(forgotEmail);
      setPassword('');
    } catch (error: any) {
      console.error(error);
      toast.error(error.response?.data?.error || 'Đặt lại mật khẩu thất bại. Vui lòng thử lại!', { id: toastId });
    } finally {
      setResetting(false);
    }
  };

  const closeForgotModal = () => {
    setShowForgotModal(false);
    setForgotStep(1);
    setOtp('');
    setNewPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-5xl overflow-hidden flex flex-col md:flex-row">

        {/* Left Side - Branding */}
        <div className="w-full md:w-1/2 bg-blue-600 p-12 flex flex-col justify-center items-center text-white">
          <div className="text-center">
            <h1 className="text-4xl font-bold mb-3">LibraryPKA</h1>
            <p className="text-blue-100 mb-8 text-sm">Hệ thống quản lý thư viện số</p>

            {/* Logo Container */}
            <div className="bg-white rounded-3xl p-8 shadow-lg mb-6">
              <div className="bg-gray-100 rounded-2xl p-8">
                <img
                  src="/images/phenikaa-logo.png"
                  alt="Phenikaa University"
                  className="w-56 h-auto mx-auto object-contain"
                />
              </div>
            </div>

            <p className="text-blue-100 italic text-sm">
              "Tri thức là sức mạnh."
            </p>
          </div>
        </div>

        {/* Right Side - Login Form */}
        <div className="w-full md:w-1/2 p-8 md:p-12">
          <div className="mb-8">
            <h2 className="text-3xl font-bold text-gray-800 mb-2">
              {isRegistering ? 'Đăng ký tài khoản' : 'Đăng nhập hệ thống'}
            </h2>
            <p className="text-gray-500 text-sm">
              {isRegistering ? 'Tạo tài khoản độc giả mới tại Thư Viện PKA' : 'Vui lòng nhập thông tin để truy cập hệ thống'}
            </p>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            {isRegistering && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Họ và tên
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full pl-11 pr-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
                    placeholder="Nhập họ và tên"
                    required
                  />
                </div>
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Email
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full pl-11 pr-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
                  placeholder="user@library.com"
                  required
                />
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="block text-sm font-medium text-gray-700">
                  Mật khẩu
                </label>
                {!isRegistering && (
                  <button
                    type="button"
                    onClick={() => {
                      setForgotEmail(email);
                      setShowForgotModal(true);
                      setForgotStep(1);
                    }}
                    className="text-sm text-blue-600 hover:text-blue-700 hover:underline font-medium focus:outline-none transition-colors"
                  >
                    Quên mật khẩu?
                  </button>
                )}
              </div>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-11 pr-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none"
                  placeholder="••••••••"
                  required
                />
              </div>
            </div>

            <div className="pt-2">
              <button
                type="submit"
                disabled={loading}
                className="w-full bg-gray-900 hover:bg-gray-800 text-white font-semibold py-3.5 rounded-lg transition-all transform hover:scale-[1.01] active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg"
              >
                <ArrowRight size={20} />
                {loading ? 'Đang xử lý...' : (isRegistering ? 'Đăng ký tài khoản' : 'Đăng nhập')}
              </button>
            </div>
          </form>

          <div className="mt-8 text-center">
            <p className="text-gray-600 text-sm">
              {isRegistering ? 'Đã có tài khoản?' : 'Chưa có tài khoản?'}
              <button
                onClick={() => setIsRegistering(!isRegistering)}
                className="ml-2 text-blue-600 hover:text-blue-700 font-semibold hover:underline focus:outline-none transition-colors"
              >
                {isRegistering ? 'Đăng nhập ngay' : 'Đăng ký ngay'}
              </button>
            </p>
          </div>
        </div>
      </div>

      {/* MODAL QUÊN MẬT KHẨU / FORGOT PASSWORD */}
      {showForgotModal && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden border border-gray-100 transition-all transform animate-in fade-in zoom-in-95">
            {/* Modal Header */}
            <div className="px-6 py-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center shadow-md">
                  {forgotStep === 1 ? <KeyRound size={20} /> : <ShieldCheck size={20} />}
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-900">
                    {forgotStep === 1 ? 'Quên mật khẩu' : 'Xác thực OTP & Đổi mật khẩu'}
                  </h3>
                  <p className="text-xs text-gray-500">
                    {forgotStep === 1 ? 'Bước 1/2: Nhập email tài khoản' : 'Bước 2/2: Nhập OTP và mật khẩu mới'}
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={closeForgotModal}
                className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-gray-200/50 transition-colors"
              >
                <X size={20} />
              </button>
            </div>

            {/* Modal Content */}
            <div className="p-6">
              {forgotStep === 1 ? (
                /* BƯỚC 1: NHẬP EMAIL */
                <form onSubmit={handleSendOtp} className="space-y-4">
                  <div className="text-sm text-gray-600 leading-relaxed">
                    Vui lòng nhập địa chỉ email đã đăng ký. Hệ thống sẽ gửi một mã xác thực <strong>OTP gồm 6 chữ số</strong> đến hòm thư của bạn.
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      Địa chỉ Email
                    </label>
                    <div className="relative">
                      <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <input
                        type="email"
                        value={forgotEmail}
                        onChange={(e) => setForgotEmail(e.target.value)}
                        placeholder="vidu: user@domain.com"
                        className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm transition-all"
                        required
                        autoFocus
                      />
                    </div>
                  </div>

                  <div className="pt-2 flex items-center justify-end gap-3">
                    <button
                      type="button"
                      onClick={closeForgotModal}
                      className="px-4 py-2 text-sm text-gray-600 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-colors font-medium"
                    >
                      Hủy bỏ
                    </button>
                    <button
                      type="submit"
                      disabled={otpSending}
                      className="px-5 py-2.5 text-sm bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {otpSending && <Loader2 size={16} className="animate-spin" />}
                      {otpSending ? 'Đang gửi mã...' : 'Gửi mã OTP'}
                    </button>
                  </div>
                </form>
              ) : (
                /* BƯỚC 2: NHẬP OTP VÀ MẬT KHẨU MỚI */
                <form onSubmit={handleResetPassword} className="space-y-4">
                  <div className="bg-blue-50 border border-blue-100 rounded-lg p-3 text-xs text-blue-800">
                    Mã OTP 6 chữ số đã được gửi tới email <strong className="font-semibold text-blue-900">{forgotEmail}</strong>. Mã này có hiệu lực trong 15 phút.
                  </div>

                  {/* Ô nhập OTP */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      Mã xác thực OTP (6 chữ số)
                    </label>
                    <div className="relative">
                      <KeyRound className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <input
                        type="text"
                        maxLength={6}
                        value={otp}
                        onChange={(e) => setOtp(e.target.value.replace(/\D/g, ''))}
                        placeholder="Ví dụ: 123456"
                        className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm tracking-widest font-mono font-semibold transition-all"
                        required
                        autoFocus
                      />
                    </div>
                    <div className="flex justify-end mt-1">
                      <button
                        type="button"
                        onClick={handleSendOtp}
                        disabled={otpSending}
                        className="text-xs text-blue-600 hover:text-blue-800 hover:underline font-medium"
                      >
                        {otpSending ? 'Đang gửi lại...' : 'Chưa nhận được mã? Gửi lại'}
                      </button>
                    </div>
                  </div>

                  {/* Mật khẩu mới */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      Mật khẩu mới
                    </label>
                    <div className="relative">
                      <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <input
                        type="password"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        placeholder="Tối thiểu 6 ký tự"
                        className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm transition-all"
                        required
                      />
                    </div>
                  </div>

                  {/* Xác nhận mật khẩu mới */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1.5">
                      Xác nhận mật khẩu mới
                    </label>
                    <div className="relative">
                      <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                      <input
                        type="password"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        placeholder="Nhập lại mật khẩu mới"
                        className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm transition-all"
                        required
                      />
                    </div>
                  </div>

                  <div className="pt-3 flex items-center justify-between border-t border-gray-100">
                    <button
                      type="button"
                      onClick={() => setForgotStep(1)}
                      className="px-3 py-2 text-sm text-gray-600 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-colors font-medium flex items-center gap-1.5"
                    >
                      <ArrowLeft size={16} /> Quay lại
                    </button>
                    <button
                      type="submit"
                      disabled={resetting}
                      className="px-5 py-2.5 text-sm bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {resetting && <Loader2 size={16} className="animate-spin" />}
                      {resetting ? 'Đang đổi mật khẩu...' : 'Xác nhận đổi mật khẩu'}
                    </button>
                  </div>
                </form>
              )}
            </div>
          </div>
        </div>
      )}

      {/* MODAL XÁC THỰC OTP ĐĂNG NHẬP 2 LỚP (2FA VERIFICATION POPUP) */}
      {showOtpModal && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden border border-gray-100 transition-all transform animate-in fade-in zoom-in-95">
            {/* Header */}
            <div className="px-6 py-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-emerald-50 to-teal-50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-emerald-600 text-white flex items-center justify-center shadow-md">
                  <ShieldCheck size={22} />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-900">
                    Xác thực 2 lớp (2FA)
                  </h3>
                  <p className="text-xs text-gray-500">
                    Bảo vệ tài khoản với mã OTP
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={handleCloseOtpModal}
                className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-gray-200/50 transition-colors"
                title="Đóng popup (Hủy xác thực)"
              >
                <X size={20} />
              </button>
            </div>

            {/* Content */}
            <div className="p-6">
              <form onSubmit={handleVerifyOtp} className="space-y-4">
                <div className="text-sm text-gray-600 leading-relaxed">
                  Tài khoản của bạn được kích hoạt bảo vệ 2 bước. Hệ thống đã gửi mã <strong>OTP gồm 6 chữ số</strong> đến địa chỉ email đăng ký.
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">
                    Mã xác thực OTP (6 chữ số)
                  </label>
                  <div className="relative">
                    <KeyRound className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input
                      type="text"
                      maxLength={6}
                      value={loginOtp}
                      onChange={(e) => setLoginOtp(e.target.value.replace(/\D/g, ''))}
                      className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 tracking-widest font-mono text-center text-xl font-bold text-gray-800 transition-all outline-none"
                      placeholder="000000"
                      autoFocus
                      required
                    />
                  </div>
                  <div className="mt-2 flex items-center justify-between text-xs text-gray-500">
                    <span>Hiệu lực trong 10 phút</span>
                    <button
                      type="button"
                      onClick={handleResendLoginOtp}
                      disabled={otpResending}
                      className="text-emerald-600 hover:text-emerald-700 font-medium hover:underline focus:outline-none disabled:opacity-50"
                    >
                      {otpResending ? 'Đang gửi lại...' : 'Chưa nhận được mã? Gửi lại'}
                    </button>
                  </div>
                </div>

                {otpPreviewUrl && (
                  <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg text-xs text-emerald-800 flex items-center justify-between">
                    <span>Thư thử nghiệm (Ethereal Email):</span>
                    <a
                      href={otpPreviewUrl}
                      target="_blank"
                      rel="noreferrer"
                      className="font-bold underline text-emerald-700 hover:text-emerald-900"
                    >
                      Mở Thư Preview ↗
                    </a>
                  </div>
                )}

                <div className="pt-2 flex gap-3">
                  <button
                    type="button"
                    onClick={handleCloseOtpModal}
                    className="w-1/3 border border-gray-300 hover:bg-gray-100 text-gray-700 font-medium py-2.5 rounded-lg transition-colors text-sm"
                  >
                    Hủy bỏ
                  </button>
                  <button
                    type="submit"
                    disabled={otpVerifying || loginOtp.length !== 6}
                    className="w-2/3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold py-2.5 rounded-lg transition-all flex items-center justify-center gap-2 shadow-md hover:shadow-lg disabled:opacity-50 text-sm"
                  >
                    {otpVerifying && <Loader2 size={16} className="animate-spin" />}
                    {otpVerifying ? 'Đang xác thực...' : 'Xác nhận & Đăng nhập'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import {
  Search, Plus, Mail, UserCheck, X, Save,
  ShieldAlert, ShieldCheck, Crown, Award, BookOpen, AlertTriangle
} from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { client } from '../api/client';
import { useLanguage } from '../contexts/LanguageContext';
import { toast } from 'sonner';

export interface Member {
  id: number;
  name: string;
  email: string;
  role: 'ADMIN' | 'USER';
  createdAt: string;
  membershipTier?: 'STANDARD' | 'PREMIUM' | 'LECTURER' | string;
  isBlacklisted?: boolean;
  phone?: string;
  membershipType?: string;
  status?: string;
  booksOut?: number;
}

export function MembersManagement() {
  const { t, language } = useLanguage();
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'ACTIVE' | 'BLACKLISTED'>('ALL');
  const [showAddModal, setShowAddModal] = useState(false);
  const queryClient = useQueryClient();

  // State form thành viên mới
  const [newMember, setNewMember] = useState({
    name: '',
    email: '',
    password: 'password123',
    role: 'USER' as 'ADMIN' | 'USER',
    membershipTier: 'STANDARD'
  });

  // Fetch Users
  const { data: members = [], isLoading } = useQuery({
    queryKey: ['users'],
    queryFn: async () => {
      const { data } = await client.get('/auth/users');
      return data as Member[];
    }
  });

  // Add User Mutation
  const addUserMutation = useMutation({
    mutationFn: async (userData: any) => {
      await client.post('/auth/register', userData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
      setShowAddModal(false);
      setNewMember({ name: '', email: '', password: 'password123', role: 'USER', membershipTier: 'STANDARD' });
      toast.success("Thêm thành viên mới thành công!");
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || "Có lỗi xảy ra khi thêm thành viên");
    }
  });

  // Toggle Blacklist Mutation
  const toggleBlacklistMutation = useMutation({
    mutationFn: async ({ id, isBlacklisted }: { id: number; isBlacklisted: boolean }) => {
      const { data } = await client.patch(`/auth/users/${id}/blacklist`, { isBlacklisted });
      return data;
    },
    onSuccess: (data) => {
      toast.success(data.message || 'Cập nhật danh sách đen thành công!');
      queryClient.invalidateQueries({ queryKey: ['users'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.error || 'Có lỗi khi cập nhật trạng thái danh sách đen');
    }
  });

  const handleToggleBlacklist = (member: Member) => {
    const willBlacklist = !member.isBlacklisted;
    const confirmMsg = willBlacklist
      ? `Bạn có chắc chắn muốn đưa độc giả "${member.name}" (${member.email}) vào DANH SÁCH ĐEN?\n⚠️ Độc giả này sẽ bị chặn ngay lập tức, không được phép mượn bất kỳ cuốn sách mới nào!`
      : `Bạn có muốn gỡ bỏ độc giả "${member.name}" khỏi Danh sách Đen và cho phép mượn sách trở lại?`;

    if (window.confirm(confirmMsg)) {
      toggleBlacklistMutation.mutate({
        id: member.id,
        isBlacklisted: willBlacklist
      });
    }
  };

  const handleAddMember = () => {
    if (!newMember.name || !newMember.email) return;
    addUserMutation.mutate(newMember);
  };

  const filteredMembers = members.filter(member => {
    const matchesSearch =
      member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      member.email.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesStatus =
      statusFilter === 'ALL' ||
      (statusFilter === 'ACTIVE' && !member.isBlacklisted) ||
      (statusFilter === 'BLACKLISTED' && member.isBlacklisted);

    return matchesSearch && matchesStatus;
  });

  const blacklistedCount = members.filter(m => m.isBlacklisted).length;
  const activeCount = members.filter(m => !m.isBlacklisted).length;

  return (
    <div className="space-y-6 relative">
      {/* Title & Action */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-1">{t('members.title')}</h2>
          <p className="text-gray-600 dark:text-gray-400">{t('members.subtitle')}</p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="bg-blue-600 text-white px-4 py-2.5 rounded-lg flex items-center gap-2 hover:bg-blue-700 transition-colors shadow-sm self-start sm:self-auto font-medium"
        >
          <Plus className="w-5 h-5" />
          {t('members.addNew')}
        </button>
      </div>

      {/* Summary KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-500 dark:text-gray-400">{language === 'vi' ? 'Tổng số độc giả' : 'Total Members'}</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{members.length}</p>
          </div>
          <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 rounded-lg">
            <UserCheck size={22} />
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-green-200 dark:border-green-900/50 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-xs text-green-700 dark:text-green-400 font-medium">{t('members.active')}</p>
            <p className="text-2xl font-bold text-green-600 dark:text-green-400 mt-1">{activeCount}</p>
          </div>
          <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 rounded-lg">
            <ShieldCheck size={22} />
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 p-4 rounded-xl border border-red-200 dark:border-red-900/50 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-xs text-red-700 dark:text-red-400 font-medium">{t('members.blacklisted')}</p>
            <p className="text-2xl font-bold text-red-600 dark:text-red-400 mt-1">{blacklistedCount}</p>
          </div>
          <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 rounded-lg">
            <ShieldAlert size={22} />
          </div>
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="flex flex-col sm:flex-row gap-3 bg-white dark:bg-gray-900 p-4 rounded-xl border border-gray-200 dark:border-gray-800 shadow-sm">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder={t('members.search')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
        </div>

        <div className="flex items-center gap-1.5">
          <button
            onClick={() => setStatusFilter('ALL')}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${statusFilter === 'ALL'
                ? 'bg-gray-900 dark:bg-gray-100 text-white dark:text-gray-900'
                : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200'
              }`}
          >
            {language === 'vi' ? 'Tất cả' : 'All'} ({members.length})
          </button>
          <button
            onClick={() => setStatusFilter('ACTIVE')}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${statusFilter === 'ACTIVE'
                ? 'bg-green-600 text-white'
                : 'bg-green-50 dark:bg-green-950/30 text-green-700 dark:text-green-300 hover:bg-green-100'
              }`}
          >
            {t('members.active')} ({activeCount})
          </button>
          <button
            onClick={() => setStatusFilter('BLACKLISTED')}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${statusFilter === 'BLACKLISTED'
                ? 'bg-red-600 text-white'
                : 'bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-300 hover:bg-red-100'
              }`}
          >
            {t('members.blacklisted')} ({blacklistedCount})
          </button>
        </div>
      </div>

      {/* Member Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {filteredMembers.map((member) => {
          const tier = (member.membershipTier || 'STANDARD').toUpperCase();
          const maxBooks = tier === 'PREMIUM' ? 10 : tier === 'LECTURER' ? 15 : 5;

          return (
            <div
              key={member.id}
              className={`bg-white dark:bg-gray-900 rounded-xl border p-5 transition-all shadow-sm hover:shadow-md flex flex-col justify-between ${member.isBlacklisted
                  ? 'border-red-300 dark:border-red-900/60 bg-red-50/20 dark:bg-red-950/10'
                  : 'border-gray-200 dark:border-gray-800'
                }`}
            >
              <div>
                {/* Header: Avatar, Name, Role & Status */}
                <div className="flex justify-between items-start mb-3">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className={`w-11 h-11 rounded-full flex items-center justify-center font-bold text-base shrink-0 ${member.isBlacklisted
                        ? 'bg-red-100 dark:bg-red-900/40 text-red-600'
                        : 'bg-blue-100 dark:bg-blue-900/30 text-blue-600'
                      }`}>
                      {member.name ? member.name.charAt(0).toUpperCase() : 'U'}
                    </div>
                    <div className="min-w-0">
                      <h3 className="font-semibold text-gray-900 dark:text-white truncate" title={member.name}>
                        {member.name}
                      </h3>
                      <div className="flex items-center gap-1.5 mt-0.5">
                        <span className={`text-[11px] font-medium px-2 py-0.5 rounded-full ${member.role === 'ADMIN'
                            ? 'bg-purple-100 dark:bg-purple-900/40 text-purple-700 dark:text-purple-300'
                            : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300'
                          }`}>
                          {member.role === 'ADMIN' ? t('header.admin') : t('header.user')}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Status Badge */}
                  {member.isBlacklisted ? (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 border border-red-200">
                      <ShieldAlert size={12} /> {t('members.blacklisted')}
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 border border-green-200">
                      <UserCheck size={12} /> {t('members.active')}
                    </span>
                  )}
                </div>

                {/* Email */}
                <div className="flex items-center gap-2 text-xs text-gray-600 dark:text-gray-400 mb-3">
                  <Mail className="w-3.5 h-3.5 text-gray-400 shrink-0" />
                  <span className="truncate">{member.email}</span>
                </div>

                {/* Membership Tier & Limits */}
                <div className="p-2.5 bg-gray-50 dark:bg-gray-800/60 rounded-lg text-xs space-y-1 mb-4">
                  <div className="flex items-center justify-between">
                    <span className="text-gray-500 flex items-center gap-1">
                      {tier === 'PREMIUM' ? <Crown size={12} className="text-amber-500" /> : <Award size={12} className="text-blue-500" />}
                      Hạng thành viên:
                    </span>
                    <span className="font-semibold text-gray-800 dark:text-gray-200">{tier}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-gray-500 flex items-center gap-1">
                      <BookOpen size={12} className="text-indigo-500" /> Hạn mức mượn:
                    </span>
                    <span className="font-medium text-indigo-600 dark:text-indigo-400">Tối đa {maxBooks} cuốn</span>
                  </div>
                </div>
              </div>

              {/* Footer: Date & Blacklist Toggle Switch */}
              <div className="pt-3 border-t border-gray-100 dark:border-gray-800 space-y-2.5">
                <div className="flex items-center justify-between text-xs text-gray-500">
                  <span>Mã thẻ: LIB-{member.id}</span>
                  <span>{new Date(member.createdAt).toLocaleDateString('vi-VN')}</span>
                </div>

                {/* --- TOGGLE BLACKLIST BUTTON --- */}
                {member.role !== 'ADMIN' && (
                  <div className="flex items-center justify-between pt-1">
                    <span className="text-xs font-medium text-gray-700 dark:text-gray-300 flex items-center gap-1">
                      {member.isBlacklisted ? (
                        <span className="text-red-600 dark:text-red-400 font-semibold flex items-center gap-1">
                          <AlertTriangle size={13} /> Chặn mượn sách
                        </span>
                      ) : (
                        <span className="text-gray-500">Quyền mượn sách</span>
                      )}
                    </span>

                    {/* Interactive Toggle Switch */}
                    <button
                      type="button"
                      onClick={() => handleToggleBlacklist(member)}
                      disabled={toggleBlacklistMutation.isPending}
                      className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${member.isBlacklisted ? 'bg-red-600' : 'bg-gray-300 dark:bg-gray-700'
                        }`}
                      role="switch"
                      aria-checked={Boolean(member.isBlacklisted)}
                      title={member.isBlacklisted ? 'Nhấn để gỡ khỏi Blacklist' : 'Nhấn để đưa vào Blacklist'}
                    >
                      <span
                        aria-hidden="true"
                        className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${member.isBlacklisted ? 'translate-x-5' : 'translate-x-0'
                          }`}
                      />
                    </button>
                  </div>
                )}
              </div>
            </div>
          );
        })}

        {filteredMembers.length === 0 && (
          <div className="col-span-full text-center py-12 text-gray-500 dark:text-gray-400">
            {isLoading ? 'Đang tải danh sách độc giả...' : 'Không tìm thấy độc giả nào phù hợp.'}
          </div>
        )}
      </div>

      {/* MODAL THÊM THÀNH VIÊN */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-900 rounded-xl w-full max-w-lg shadow-2xl p-6 border border-gray-200 dark:border-gray-800">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">Thêm thành viên mới</h3>
              <button onClick={() => setShowAddModal(false)} className="text-gray-400 hover:text-gray-600">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Họ và tên</label>
                <input
                  type="text"
                  value={newMember.name}
                  onChange={e => setNewMember({ ...newMember, name: e.target.value })}
                  className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                  placeholder="Nhập họ tên độc giả..."
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Email</label>
                <input
                  type="email"
                  value={newMember.email}
                  onChange={e => setNewMember({ ...newMember, email: e.target.value })}
                  className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                  placeholder="example@email.com"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Mật khẩu mặc định</label>
                <input
                  type="text"
                  value={newMember.password}
                  disabled
                  className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg text-gray-500 text-sm"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Vai trò</label>
                  <select
                    value={newMember.role}
                    // @ts-ignore
                    onChange={e => setNewMember({ ...newMember, role: e.target.value })}
                    className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                  >
                    <option value="USER">Độc giả (User)</option>
                    <option value="ADMIN">Quản trị viên (Admin)</option>
                  </select>
                </div>

                <div>
